  ui_story_5009_50090301_28_dialog_content = "Eles são uma das guildas mais famosas do mundo. Vice e Carleen, vocês dois devem saber deles.",
  ui_story_5009_50090301_29_dialog_content = "Sim, também sei que os Lins se davam bem com os Caelestitas e as Terras do Norte.",
  ui_story_5009_50090301_30_dialog_content = "Parece que Naroxel está correto ao dizer que os Lins enterraram os mortos de Eraveil de acordo com seus costumes.",
  ui_story_5009_50090301_31_dialog_content = "Para os Celestitas, descansar na terra representa um retorno à natureza, da qual nos tornaremos parte após a morte.",
  ui_story_5009_50090301_32_dialog_content = "A Guilda Lin…",
  ui_story_5009_50090301_33_dialog_content = "Vamos primeiro terminar o que viemos fazer aqui.",
  ui_story_5009_50090301_34_dialog_content = "Tá bom.",
  ui_story_5009_50090302_1_dialog_content = "A memorável torre branca conhecida como Farol do Vale Profundo…",
  ui_story_5009_50090302_2_dialog_content = "não deve estar muito à frente.",
  ui_story_5009_50090302_3_dialog_content = "Vamos nos dividir em dois grupos. Vou lidar com os Eclipsites com o Vice e os outros. Você vai para o posto.",
  ui_story_5009_50090302_4_dialog_content = "Ok! Eu colo lápido. Vou lá olhar!",
  ui_story_5009_50090302_5_dialog_content = "E nós vamos consertar o correio.",
  ui_story_5009_50090302_6_dialog_content = "Nós prometemos que você verá um local novinho quando voltar.",
  ui_story_5009_50090302_7_dialog_content = "Eu sei que sim. Valeu.",
  ui_story_5009_50090302_8_dialog_content = "Vamos continuar indo para o leste e enfrentar os Eclipsitas lá.",
  ui_story_5009_50090302_9_dialog_content = "Ah, sua presença também é necessária para uma cerimônia.",
  ui_story_5009_50090302_10_dialog_content = "Que cerimônia?",
  ui_story_5009_50090302_11_dialog_content = "Não se preocupe, só vai durar alguns minutos.",
  ui_story_5009_50090302_12_dialog_content = "Primeiro, devemos verificar sua identidade. Embora, é claro, isso já tenha sido feito.",
  ui_story_5009_50090302_13_dialog_content = "Depois, você precisa assinar dois documentos.",
  ui_story_5009_50090302_14_dialog_content = "O primeiro é o Acordo da Estação. Por favor, assine-o e depois assine a Permissão para Trabalhar.",
  ui_story_5009_50090302_15_dialog_content = "Parece complicado... Deixe-me dar uma olhada mais de perto.",
  ui_story_5009_50090302_16_dialog_content = "É realmente necessário fazer isso antes da batalha?",
  ui_story_5009_50090302_17_dialog_content = "<color=#e8d9bb>Alguns minutos depois...</color>",
  ui_story_5009_50090302_18_dialog_content = "Meus olhos estão embaçados… Eu vou só assinar isso.",
  ui_story_5009_50090302_19_dialog_content = "Por último, temos um Documento de Verificação…",
  ui_story_5009_50090302_20_dialog_content = "Eu também tenho que assinar isso? Eita, também é grande!",
  ui_story_5009_50090302_21_dialog_content = "Apenas assine! A União é confiável, eles não vão enganá-lo.",
  ui_story_5009_50090302_22_dialog_content = "Porém, para documentos estranhos de qualquer outra pessoa, certifique-se de lê-los por inteiro!",
  ui_story_5009_50090302_23_dialog_content = "Esse pode esperar até o correio ser reconstruído.",
  ui_story_5009_50090302_24_dialog_content = "Além disso, depois que chegarmos ao correio da Torre Branca…",
  ui_story_5009_50090302_25_dialog_content = "Vamos enviar as coordenadas para a União e disponibilizar o relatório de dano.",
  ui_story_5009_50090302_26_dialog_content = "A União enviará a ajuda de forma adequada, então podemos concluir hoje.",
  ui_story_5009_50090302_27_dialog_content = "Por favor, espere ansiosamente pelas novas instalações.",
  ui_story_5009_50090302_28_dialog_content = "Naroxel, eu achei a Torre Branca ali!",
  ui_story_5009_50090302_29_dialog_content = "Bem, vamos então.",
  ui_story_5009_50090302_30_dialog_content = "Boa luta wuck, PlayerName!",
  ui_story_5009_50090302_31_dialog_content = "Vou tentar o meu melhor!",
  ui_story_5009_50090302_32_dialog_content = "Vamos acabar com todos os Eclipsitas em Eraveil!",
  ui_story_5009_50090401_1_dialog_content = "Alvo localizado à nordeste, meu senhor!",
  ui_story_5009_50090401_2_dialog_content = "Meu meu. A adorável princesa entra no vale para um encontro com seu encantador cavaleiro...",
  ui_story_5009_50090401_3_dialog_content = "Que história chata é essa? Eu odiei!",
  ui_story_5009_50090401_4_dialog_content = "Bem, a nossa chance é agora!",
  ui_story_5009_50090401_5_dialog_content = "Mas há muitos aurorianos em Eraveil agora...",
  ui_story_5009_50090401_6_dialog_content = "Fazer um movimento... pode ser arriscado.",
  ui_story_5009_50090401_7_dialog_content = "Você acha que não consigo derrotá-los?",
  ui_story_5009_50090401_8_dialog_content = "Eu vou te devorar por ter acabado com a minha disposição!",
  ui_story_5009_50090401_9_dialog_content = "M-Meu senhor...?",
  ui_story_5009_50090401_10_dialog_content = "Hahaha! Você está tremendo?",
  ui_story_5009_50090401_11_dialog_content = "Vou te poupar dessa vez só porque você consegue falar Universês.",
  ui_story_5009_50090401_12_dialog_content = "Mas, mas… o Celestita também está aqui.",
  ui_story_5009_50090401_13_dialog_content = "Ouvi dizer que ele pode nos sentir usando habilidades psíquicas.",
  ui_story_5009_50090401_14_dialog_content = "E daí?",
  ui_story_5009_50090401_15_dialog_content = "Sabe, talvez eu também capture o Celestita, para o jantar.",
  ui_story_5009_50090401_16_dialog_content = "Eu sou genial!",
  ui_story_5009_50090401_17_dialog_content = "Avise os outros Eclipsitas insignificantes para que se prepararem!",
  ui_story_5009_50090401_18_dialog_content = "Como está sua habilidade psíquica, PlayerName?",
  ui_story_5009_50090401_19_dialog_content = "Eu não diria que é muito poderoso, mas é mais do que adequado.",
  ui_story_5009_50090401_20_dialog_content = "Consigo sentir a localização dos Eclipsitas a distância e dizer quais deles são especiais.",
  ui_story_5009_50090401_21_dialog_content = "Se importa em descrever o que é diferente nos Eclipsitas especiais que encontrou na Linha Dunafogo?",
  ui_story_5009_50090401_22_dialog_content = "A maioria deles era do tipo médio, apenas mais feroz.",
  ui_story_5009_50090401_23_dialog_content = "Mas as elites que conhecemos em Undercity 13 eram muito inteligentes. Eles eram lutadores.",
  ui_story_5009_50090401_24_dialog_content = "Além disso, eles eram capazes de sondar aberturas e usar tempestades de areia como cobertura.",
  ui_story_5009_50090401_25_dialog_content = "Sim, eu também notei as tempestades de areia.",
  ui_story_5009_50090401_26_dialog_content = "De acordo com minhas descobertas, as tempestades de areia e os fluxos de energia em Dunefire podem não ter sido fenômenos naturais.",
  ui_story_5009_50090401_27_dialog_content = "Pelo menos, não totalmente natural.",
  ui_story_5009_50090401_28_dialog_content = "Você está dizendo que os Eclipsitas podem controlar o tempo agora?",
  ui_story_5009_50090401_29_dialog_content = "É só um palpite. Preciso de mais provas.",
  ui_story_5009_50090401_30_dialog_content = "E há algo ainda mais complicado.",
  ui_story_5009_50090401_31_dialog_content = "Aquietem-se. Sinto um grupo grande de Eclipsitas à frente.",
  ui_story_5009_50090401_32_dialog_content = "Eu vou liderar. Eu darei o julgamento apropriado...",
  ui_story_5009_50090401_33_dialog_content = "E aniquilar todos eles!",
  ui_story_5009_50090502_1_dialog_content = "Tudo livre aqui! Vamos para o próximo local.",
  ui_story_5009_50090502_2_dialog_content = "Espere, tem algo errado!",
  ui_story_5009_50090502_3_dialog_content = "Quem é você?",
  ui_story_5009_50090502_4_dialog_content = "Você fala Universês, Eclipsita?",
  ui_story_5009_50090502_5_dialog_content = "Você deve ser o arqui-inimigo que meu mestre mencionou…",
  ui_story_5009_50090502_6_dialog_content = "Uau, os Eclipsites também podem tagarelar sem sentido agora?",
  ui_story_5009_50090502_7_dialog_content = "Um número considerável de lacaios dessa vez… Parece que veio preparado.",
  ui_story_5009_50090502_8_dialog_content = "Isso vai ser divertido.",
  ui_story_5009_50090502_9_dialog_content = "Por que você está olhando para o espaço, PlayerName?",
  ui_story_5009_50090502_10_dialog_content = "Acabei de sentir uma grande horda de eclipsitas convergindo para o cemitério!",
  ui_story_5009_50090502_11_dialog_content = "Então precisamos ir para lá agora mesmo!",
  ui_story_5009_50090502_12_dialog_content = "Não adianta, já desapareceram.",
  ui_story_5009_50090502_13_dialog_content = "Já era?",
  ui_story_5009_50090502_14_dialog_content = "Agora mesmo...",
  ui_story_5009_50090502_15_dialog_content = "Uma energia poderosa foi liberada no cemitério e os Eclipsitas desapareceram.",
  ui_story_5009_50090502_16_dialog_content = "Pude sentir que era um poder de Aurorian...",
  ui_story_5009_50090502_17_dialog_content = "Essa Aurorian é amiga… ou inimiga?",
  ui_story_5009_50090502_18_dialog_content = "Ainda não sei, mas este auroriano pode esconder suas flutuações de energia!",
  ui_story_5009_50090502_19_dialog_content = "Agora, não consigo sentir sua presença.",
  ui_story_5009_50090502_20_dialog_content = "Por que estão se escondendo? Seria algum tipo de inimigo desconhecido?",
  ui_story_5009_50090502_21_dialog_content = "Precisamos ter cuidado...",
  ui_story_5009_50090602_1_dialog_content = "Sente alguma coisa, PlayerName?",
  ui_story_5009_50090602_2_dialog_content = "O mesmo auroriano de antes. Alguém muito poderoso...",
  ui_story_5009_50090602_3_dialog_content = "Será que é a Naroxel? Ela é poderosa.",
  ui_story_5009_50090602_4_dialog_content = "Só trouxe o Pittman comigo.",
  ui_story_5009_50090602_5_dialog_content = "Mas você deve conhecê-los.",
  ui_story_5009_50090602_6_dialog_content = "Como eu suspeitava, aquele auroriano não veio com vocês.",
  ui_story_5009_50090602_7_dialog_content = "Deveríamos mandar alguém pra verificar?",
  ui_story_5009_50090602_8_dialog_content = "Não precisa. Lembro que a Naroxel comentou que a União Mensageira mandaria alguém.",
  ui_story_5009_50090602_9_dialog_content = "Talvez seja um membro da União.",
  ui_story_5009_50090602_10_dialog_content = "Sobre o que estão falando, soldados?",
  ui_story_5009_50090602_11_dialog_content = "Tenente Vice, estávamos falando sobre como Eraveil lutou contra os Eclipsites no passado.",
  ui_story_5009_50090602_12_dialog_content = "Há uma linha Illumina impenetrável entre Eraveil e o antigo covil Eclipsite.",
  ui_story_5009_50090602_13_dialog_content = "O terreno difícil de Eraveil facilita a defesa e dificulta o ataque dos inimigos.",
  ui_story_5009_50090602_14_dialog_content = "Mas Celestitas não podem lutar. O que acontece quando têm que se defender de Eclipsitas?",
  ui_story_5009_50090602_15_dialog_content = "Eles podiam sentir os movimentos dos Eclipsitas e planejar com antecedência.",
  ui_story_5009_50090602_16_dialog_content = "Illumina e Lumópolis mandavam representantes e provisões para Eraveil com frequência.",
  ui_story_5009_50090602_17_dialog_content = "Sim, Eraveil é um osso duro de roer.",
  ui_story_5009_50090602_18_dialog_content = "Mas se conseguem entrar, é fim de jogo.",
  ui_story_5009_50090602_19_dialog_content = "Você com certeza sabe como isso termina.",
  ui_story_5009_50090602_20_dialog_content = "Como os Eclipsitas passaram pela linha Illumina e entraram em Eraveil?",
  ui_story_5009_50090602_21_dialog_content = "Havia um traidor entre nós.",
  ui_story_5009_50090602_22_dialog_content = "Quanto mais invulnerável é a sua defensa, mais fácil é derrubada por traição.",
  ui_story_5009_50090602_23_dialog_content = "E houve um eclipse naquele dia, então todos os sistemas de defesa caíram.",
  ui_story_5009_50090701_1_dialog_content = "Sou só eu ou ficou muito escuro do nada?",
  ui_story_5009_50090701_2_dialog_content = "Era para ser dia, mas está escuro como a noite.",
  ui_story_5009_50090701_3_dialog_content = "Um eclipse assim que mencionei um? Como isso pode ser?",
  ui_story_5009_50090701_4_dialog_content = "Mas julgando pela auréola cor de sangue no céu, é um eclipse!",
  ui_story_5009_50090701_5_dialog_content = "Isso deve ser apenas um fenômeno semelhante, tem que ser!",
  ui_story_5009_50090701_6_dialog_content = "Cuidado, pessoal, sinto uma estranha perturbação!",
  ui_story_5009_50090701_7_dialog_content = "Eraveil, eclipse...",
  ui_story_5009_50090701_8_dialog_content = "Este é o destino inevitável de um celestita?",
  ui_story_5009_50090701_9_dialog_content = "Fique calmo, PlayerName!",
  ui_story_5009_50090701_10_dialog_content = "Pare de pensar demais e concentre-se no presente.",
  ui_story_5009_50090701_11_dialog_content = "Você tem razão. Tudo bem agora.",
  ui_story_5009_50090701_12_dialog_content = "Será que é aquela pessoa que senti mais cedo?",
  ui_story_5009_50090701_13_dialog_content = "Aquela com habilidades furtivas?",
  ui_story_5009_50090701_14_dialog_content = "O céu escuro, a coroa escarlate.",
  ui_story_5009_50090701_15_dialog_content = "Você está prestes a fazer uma jogada...",
  ui_story_5009_50090701_16_dialog_content = "Mas dessa vez, não será poupado!",
  ui_story_5009_50090702_1_dialog_content = "O que está acontecendo?",
  ui_story_5009_50090702_2_dialog_content = "Gah!",
  ui_story_5009_50090702_3_dialog_content = "Não entrar em pânico! Mate o Eclipsite primeiro!",
  ui_story_5009_50090702_4_dialog_content = "De alguma forma... não consigo usar todo o meu poder, Carleen...",
  ui_story_5009_50090702_5_dialog_content = "Eu me sinto da mesma forma.",
  ui_story_5009_50090702_6_dialog_content = "E você, PlayerName?",
  ui_story_5009_50090702_7_dialog_content = "Estou bem, é que...",
  ui_story_5009_50090702_8_dialog_content = "Bem o quê?",
  ui_story_5009_50090702_9_dialog_content = "Minha habilidade psíquica parece ter enfraquecido. Não sinto o que acontece ao longe.",
  ui_story_5009_50090702_10_dialog_content = "Nossa Luminática também foi suprimida.",
  ui_story_5009_50090702_11_dialog_content = "Se não estou errado, é devido ao eclipse.",
  ui_story_5009_50090702_12_dialog_content = "Fiquem alertas, e cuidado com emboscadas de Eclipsitas!",
  ui_story_5009_50090702_13_dialog_content = "Estou preocupado com o grupo do posto... Deixe-me tentar alcançá-los.",
  ui_story_5009_50090702_14_dialog_content = "Não consigo alcançá-los!",
  ui_story_5009_50090702_15_dialog_content = "Portanto, as comunicações também estão inativas.",
  ui_story_5009_50090702_16_dialog_content = "Será que conseguimos ir encontrar a Naroxel no posto?",
  ui_story_5009_50090702_17_dialog_content = "Eu vou na frente.",
  ui_story_5009_50090702_18_dialog_content = "Não consigo sentir o que está acontecendo desta distância, estou preocupado que os Eclipsites nos cerquem...",
  ui_story_5009_50090702_19_dialog_content = "Vamos te dar cobertura, Ten. Vice.",
  ui_story_5009_50090702_20_dialog_content = "Certo, conto com você.",
  ui_story_5009_50090702_21_dialog_content = "Vamos, PlayerName!",
  ui_story_5009_50090801_1_dialog_content = "Explosão chegando!",
  ui_story_5009_50090801_2_dialog_content = "Cuidado!",
  ui_story_5009_50090801_3_dialog_content = "Cuidado!",
  ui_story_5009_50090801_4_dialog_content = "Que pena que não acertou.",
  ui_story_5009_50090801_5_dialog_content = "Tá preparado?",
  ui_story_5009_50090801_6_dialog_content = "Estou indo te encontrar.",
  ui_story_5009_50090801_7_dialog_content = "Estão todos bem?",
  ui_story_5009_50090801_8_dialog_content = "Estou bem. E você, PlayerName?",
  ui_story_5009_50090801_9_dialog_content = "Tô bem.",
  ui_story_5009_50090801_10_dialog_content = "Eu já me acostumei.",
  ui_story_5009_50090801_11_dialog_content = "Onde estamos?",
  ui_story_5009_50090801_12_dialog_content = "PlayerName, você sabia que um lugar tão estranho existia em Eraveil?",
  ui_story_5009_50090801_13_dialog_content = "Não. Só tenho a estranha sensação que minhas habilidades psíquicas estão…",
  ui_story_5009_50090801_14_dialog_content = "É o que? Você está machucado?",
  ui_story_5009_50090801_15_dialog_content = "De jeito nenhum. É que... esse sentimento é difícil de descrever, é como... como...",
  ui_story_5009_50090801_16_dialog_content = "Como se meu nariz estivesse todo entupido!",
  ui_story_5009_50090801_17_dialog_content = "Agora não é hora pra piadinhas!",
  ui_story_5009_50090801_18_dialog_content = "Desculpe, mas é realmente como me sinto.",
  ui_story_5009_50090801_19_dialog_content = "Diferente de antes, não consigo usar meu poder de jeito nenhum.",
  ui_story_5009_50090801_20_dialog_content = "Se não podemos confiar nas habilidades de PlayerName...",
  ui_story_5009_50090801_21_dialog_content = "Precisamos ter ainda mais cuidado quando lutarmos aqui.",
  ui_story_5009_50090801_22_dialog_content = "Cuidado, Vossa Alteza!",
  ui_story_5009_50090801_23_dialog_content = "!!!",
  ui_story_5009_50090801_24_dialog_content = "Que pena, estava perto de lhe capturar…",
  ui_story_5009_50090801_25_dialog_content = "Vossa Alteza, Carleen.",
  ui_story_5009_50090801_26_dialog_content = "Quem é você?",
  ui_story_5009_50090801_27_dialog_content = "É uma honra que pergunte por meu nome!",
  ui_story_5009_50090801_28_dialog_content = "Sou...",
  ui_story_5009_50090801_A1_dialog_content = "Ah, parece que esqueci quem eu sou.",
  ui_story_5009_50090801_29_dialog_content = "...",
  ui_story_5009_50090801_30_dialog_content = "Nenhuma reação?",
  ui_story_5009_50090801_31_dialog_content = "Você deveria estar gritando: \"Que tipo de piada é essa?\" ou \"Diga-me quem você é!\" no topo de seus pulmões em um momento como este.",
  ui_story_5009_50090801_32_dialog_content = "Que nojo.",
  ui_story_5009_50090801_33_dialog_content = "Pare de gastar saliva, Carleen.",
  ui_story_5009_50090801_34_dialog_content = "É só matar!",
  ui_story_5009_50090801_35_dialog_content = "Acabei de tentar, Vice, mas ainda não recuperei meus poderes.",
  ui_story_5009_50090801_36_dialog_content = "Sem problemas. Nós cuidaremos da luta!",
  ui_story_5009_50090801_37_dialog_content = "Vice, Pittman, me deem cobertura.",
  ui_story_5009_50090801_38_dialog_content = "Vai lutar comigo?",
  ui_story_5009_50090801_39_dialog_content = "Ah, que emocionante!",
  ui_story_5009_50090801_40_dialog_content = "Venha, minha Princesa Carleen!",
  ui_story_5009_50090801_41_dialog_content = "Gelescer!",
  ui_story_5009_50090801_42_dialog_content = "Hum...",
  ui_story_5009_50090801_43_dialog_content = "Como é que não doeu nem um pouco?",
  ui_story_5009_50090801_44_dialog_content = "Lutemos em grupo, Carleen!",
  ui_story_5009_50090801_45_dialog_content = "Ah, esse tipo de luta...",
  ui_story_5009_50090801_46_dialog_content = "É tão feia!",
  ui_story_5009_50090801_47_dialog_content = "!!!",
  ui_story_5009_50090801_48_dialog_content = "Todos vocês foram espancados tão facilmente.",
  ui_story_5009_50090801_49_dialog_content = "Você não chega nem perto de ser páreo para mim!",
  ui_story_5009_50090801_50_dialog_content = "O que você quer dizer?",
  ui_story_5009_50090801_51_dialog_content = "Shh, não interrompa. Você me decepciona, Carleen.",
  ui_story_5009_50090801_52_dialog_content = "O seu jeito de lutar foi feio e inadequado para uma princesa.",
  ui_story_5009_50090801_53_dialog_content = "Eu estava querendo fazer uma bela pintura sua, mas agora perdi todo interesse.",
  ui_story_5009_50090801_54_dialog_content = "É culpa sua arruinar a visão de Gautier.",
  ui_story_5009_50090801_55_dialog_content = "Gautier? O sobrenome que foi apagado dos registros?",
  ui_story_5009_50090801_56_dialog_content = "Além de Beryl Gautier, há apenas...",
  ui_story_5009_50090801_57_dialog_content = "Você deve ser Mirren Gautier!",
  ui_story_5009_50090801_58_dialog_content = "Uau, alguém aqui me reconhece?",
  ui_story_5009_50090801_59_dialog_content = "Você esteve na minha lista de desafetos por muito tempo. Não esperava que justo hoje o encontraria.",
  ui_story_5009_50090801_60_dialog_content = "Você é um refugiado e um traidor!",
  ui_story_5009_50090801_61_dialog_content = "Sem nervosismo! Pelo menos não antes de me agradecer por anunciar meu nome!",
  ui_story_5009_50090801_62_dialog_content = "Mirren… Gautier?",
  ui_story_5009_50090801_63_dialog_content = "Sim, Vossa Alteza, Mirren Gautier, o cérebro por trás da insurreição de Pyrrhus e Gautier!",
  ui_story_5009_50090801_64_dialog_content = "Então ele é de Lumópolis?",
  ui_story_5009_50090801_65_dialog_content = "Do jeito que ele está agora, ele parece estranho mesmo para os padrões da Eclipsite.",
  ui_story_5009_50090801_66_dialog_content = "Mais um traidor Lumopolis e auroriano...",
  ui_story_5009_50090801_67_dialog_content = "Aceite sua sentença, Mirren Gautier!",
  ui_story_5009_50090801_68_dialog_content = "Espero que não esteja apenas falando da boca pra fora.",
  ui_story_5009_50090801_69_dialog_content = "Eu vou segurá-lo, você vai encontrar uma saída, PlayerName!",
  ui_story_5009_50090801_70_dialog_content = "todos seguem PlayerName. Eu cobrirei a retaguarda.",
  ui_story_5009_50090801_71_dialog_content = "Espera, aonde estão indo?",
  ui_story_5009_50090801_72_dialog_content = "Fooey, eles partiram...",
  ui_story_5009_50090801_73_dialog_content = "Aceite sua sentença, pecador!",
  ui_story_5009_50090801_74_dialog_content = "Suas tentativas são inúteis. Você acha que esses ataques fracos teriam algum efeito sobre mim?",
  ui_story_5009_50090801_75_dialog_content = "Isso é ridículo.",
  ui_story_5009_50090801_76_dialog_content = "Decidi te fazer sofrer até morrer, e então fazer o mesmo com eles.",
  ui_story_5009_50090801_77_dialog_content = "Mas deixe-me oferecer-lhe alguns conselhos amigáveis primeiro...",
  ui_story_5009_50090801_78_dialog_content = "Aquele imprestável Celestita nunca irá sair daqui.",
  ui_story_5009_50090801_79_dialog_content = "Esse é o poder do Eclipse!",
  ui_story_5009_50090801_80_dialog_content = "Vejo que suas pernas não são a única coisa que estragou durante o processo de transformação...",
  ui_story_5009_50090801_81_dialog_content = "mas seus olhos e cabeça também!",
  ui_story_5009_50090801_82_dialog_content = "Hahahaha, bem. Seu corpo é o único que vai ficar confuso em breve!",
  ui_story_5009_50090801_83_dialog_content = "Vice, Carleen, acho que chegamos no final!",
  ui_story_5009_50090801_84_dialog_content = "Sim, consigo sentir uma parede invisível.",
  ui_story_5009_50090801_85_dialog_content = "Fique de lado, PlayerName.",
  ui_story_5009_50090801_86_dialog_content = "Temos que acertar no mesmo lugar, Vice.",
  ui_story_5009_50090801_87_dialog_content = "Rogério! Torrente Rápido!",
  ui_story_5009_50090801_88_dialog_content = "Claramente acertamos, mas não há sinal de dano algum.",
  ui_story_5009_50090801_89_dialog_content = "Procure qualquer coisa incomum nas redondezas que poderia ser uma saída.",
  ui_story_5009_50090801_90_dialog_content = "Não, não vi nenhum.",
  ui_story_5009_50090801_91_dialog_content = "Existe mesmo uma saída dessa dimensão esquisita?",
  ui_story_5009_50090801_92_dialog_content = "Droga…",
  ui_story_5009_50090801_93_dialog_content = "Posso sentir todo o resto normalmente, até mesmo o som da luta deles.",
  ui_story_5009_50090801_94_dialog_content = "Minha habilidade psíquica ainda não funciona!",
  ui_story_5009_50090801_95_dialog_content = "Temo que Pittman não dure muito sozinho. Se as coisas continuarem assim…",
  ui_story_5009_50090801_96_dialog_content = "O quê? Você só chegou até aqui?",
  ui_story_5009_50090801_97_dialog_content = "Cadê o Pittman?",
  ui_story_5009_50090801_98_dialog_content = "Como ele espera me parar com uma tentativa tão patética?",
  ui_story_5009_50090801_99_dialog_content = "Ah, aí está ele, mancando pra cá agora. Não é cômico?",
  ui_story_5009_50090801_100_dialog_content = "Você tá ferido, Pittman!",
  ui_story_5009_50090801_101_dialog_content = "Cof… Ainda posso lutar… Não se preocupe comigo…",
  ui_story_5009_50090801_102_dialog_content = "Muito bom!",
  ui_story_5009_50090801_103_dialog_content = "Agora, continuamos o jogo?",
  ui_story_5009_50090801_104_dialog_content = "Haha!",
  ui_story_5009_50090901_1_dialog_content = "Ataque Rastreador!",
  ui_story_5009_50090901_2_dialog_content = "Ahn? Ah, quando se trata de ataques furtivos…",
  ui_story_5009_50090901_3_dialog_content = "Sou mesmo especialista.",
  ui_story_5009_50090901_4_dialog_content = "Hum...",
  ui_story_5009_50090901_5_dialog_content = "Mirren ainda podia usar a Luminática de Lumópolis, como é possível?",
  ui_story_5009_50090901_6_dialog_content = "Como você tá, Vice?",
  ui_story_5009_50090901_7_dialog_content = "Deixa eu tentar!",
  ui_story_5009_50090901_8_dialog_content = "Nunca diga isso até poder lutar melhor do que eles.",
  ui_story_5009_50090901_9_dialog_content = "Esse é meu conselho pra você, Celestita.",
  ui_story_5009_50090901_10_dialog_content = "Você iniciou o eclipse e nos prendeu nessa dimensão de bolso...",
  ui_story_5009_50090901_11_dialog_content = "Ah, essas são as habilidades extraordinárias que o grande mestre me deu. Me libertou pra eu seguir meu próprio destino!",
  ui_story_5009_50090901_12_dialog_content = "Blá, blá, blá. Não passa de transformação, e não é novidade pra nós também. Schummer, pelo menos...",
  ui_story_5009_50090901_13_dialog_content = "Ah, você é engraçado, pequeno Celestita.",
  ui_story_5009_50090901_14_dialog_content = "Estimados convidados Aurorians, realmente esperam que um Celestita os salve apenas com palavras?",
  ui_story_5009_50090901_15_dialog_content = "Você já falou o bastante!",
  ui_story_5009_50090901_16_dialog_content = "Deixe a luta comigo, PlayerName. Você encontra a saída.",
  ui_story_5009_50090901_17_dialog_content = "Ei, espera aqui um minuto. Ainda não fazem ideia do que está acontecendo, né?",
  ui_story_5009_50090901_18_dialog_content = "Esse é o meu mundo.",
  ui_story_5009_50090901_19_dialog_content = "Um último lembrete de que não é inteligente se opor a mim aqui.",
  ui_story_5009_50090901_20_dialog_content = "Baboseira!",
  ui_story_5009_50090901_21_dialog_content = "Aqui é Eraveil, e não pertence a você!",
  ui_story_5009_50090901_22_dialog_content = "Não vou tolerar suas ações aqui!",
  ui_story_5009_50090901_23_dialog_content = "Sério? Por que não me mostra do que é capaz?",
  ui_story_5009_50090901_24_dialog_content = "Se você se esforçar bastante, vou considerar uma morte rápida pra você.",
  ui_story_5009_50090901_25_dialog_content = "Agora, você não pode dizer que não te dei uma chance! O que acha, Carleen? Opa, perdão pela grosseria.",
  ui_story_5009_50090901_26_dialog_content = "No entanto... Hmm...",
  ui_story_5009_50090901_27_dialog_content = "Deveria me dirigir a você como Vossa Alteza ou Capitã?",
  ui_story_5009_50090901_28_dialog_content = "Você não tem permissão pra chamá-la por nenhum dos títulos!",
  ui_story_5009_50090901_29_dialog_content = "Traidor da Luz, criminoso de Lumópolis… *Cof*",
  ui_story_5009_50090901_30_dialog_content = "Você tá ferido, Pittman!",
  ui_story_5009_50090901_31_dialog_content = "A traição nunca acaba bem, Mirren Gautier.",
  ui_story_5009_50090901_32_dialog_content = "Minha lança será o seu veredito.",
  ui_story_5009_50090901_33_dialog_content = "Opa, minhas desculpas, Carleen, velha personificação da justiça!",
  ui_story_5009_50090901_34_dialog_content = "Vejo o quão errado fui. Devo ficar de joelhos e pedir perdão?",
  ui_story_5009_50090901_35_dialog_content = "Não fiz de propósito, de verdade... Hahaha!",
  ui_story_5009_50090901_36_dialog_content = "Morra, Mirren Gautier!",
  ui_story_5009_50090901_37_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5009_50090901_38_dialog_content = "Por que esse nome soa tão mal quando falado por você?",
  ui_story_5009_50090901_39_dialog_content = "Gautier é um sobrenome nobre, passado de geração a geração em Lumópolis, indigno de pertencer a alguém como você!",
  ui_story_5009_50090901_40_dialog_content = "Ah, sério? Os Gautier há muito tempo estão sob o domínio de vocês, Schwartz... Ou melhor, da grande Lumópolis.",
  ui_story_5009_50090901_41_dialog_content = "Minha família, nosso nome, nossa glória… Você arruinou tudo sem motivo, há muito tempo…",
  ui_story_5009_50090901_42_dialog_content = "Baboseira!",
  ui_story_5009_50090901_43_dialog_content = "Lumópolis pegou muito leve com os Gautier e Pyrrhuses depois da insurgência.",
  ui_story_5009_50090901_44_dialog_content = "Até que finalmente foram obrigados a tomar medidas extremas.",
  ui_story_5009_50090901_45_dialog_content = "Vocês mereciam o que receberam.",
  ui_story_5009_50090901_46_dialog_content = "É isso que você leu nos livros, querida princesa?",
  ui_story_5009_50090901_47_dialog_content = "Não surpreende, uma vez que a história de Lumópolis, assim como você...",
  ui_story_5009_50090901_48_dialog_content = "É facilmente manipulada por outros.",
  ui_story_5009_50090901_49_dialog_content = "Chega de gastar saliva com esse verme, Vossa Alteza.",
  ui_story_5009_50090901_50_dialog_content = "Mais precisamente, temos aqui o líder da insurreição e um criminoso procurado.",
  ui_story_5009_50090901_51_dialog_content = "Venha, Vossa Alteza! Acha que está em seu tribunal de justiça cheio de si?",
  ui_story_5009_50090901_52_dialog_content = "Gostaria que eu me ajoelhasse e pedisse perdão também?",
  ui_story_5009_50090901_53_dialog_content = "Você fala demais, Mirren!",
  ui_story_5009_50090901_54_dialog_content = "Ele provavelmente guardou isso por muito tempo e estava só esperando uma chance de desabafar.",
  ui_story_5009_50090901_55_dialog_content = "Ele soa como um vilão que foi injustiçado. Mas onde foi que eu vi isso antes?...",
  ui_story_5009_50090901_56_dialog_content = "Extravasar? Injustiçado? Não, não, não.",
  ui_story_5009_50090901_57_dialog_content = "Embora os Gautier injustiçados e assassinados por Lumópolis devam em breve poder desabafar com você.",
  ui_story_5009_50090901_58_dialog_content = "Exceto pela nossa nobre Carleen, o resto de vocês tem que morrer.",
  ui_story_5009_50090901_59_dialog_content = "Traidor sem vergonha! Você começou a rebelião! Você é o verdadeiro assassino!",
  ui_story_5009_50090901_60_dialog_content = "Essa é a conclusão ou o veredito, Vossa Alteza?",
  ui_story_5009_50090901_61_dialog_content = "Heh, a sentença não tem sentido sem poder de verdade.",
  ui_story_5009_50090901_62_dialog_content = "Você pode perguntar a verdade ao meu povo depois de morrer.",
  ui_story_5009_50090901_63_dialog_content = "Agora, lhe darei...",
  ui_story_5009_50090901_64_option_content = "Explosão chegando!",
  ui_story_5009_50090901_65_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5009_50090901_66_dialog_content = "Que diabos...?",
  ui_story_5009_50090901_67_dialog_content = "Solte-se!",
  ui_story_5009_50090901_68_dialog_content = "Argh!",
  ui_story_5009_50090901_69_dialog_content = "Estão todos bem?",
  ui_story_5009_50090901_70_dialog_content = "Estou aqui, PlayerName. Todos estão bem.",
  ui_story_5009_50090901_71_dialog_content = "Saímos!",
  ui_story_5009_50090901_72_dialog_content = "Sua Luminática é realmente incrível, Capitã Carleen.",
  ui_story_5009_50090901_73_dialog_content = "Não fui eu.",
  ui_story_5009_50090901_74_dialog_content = "Fiquem alertas, ainda estamos sob o eclipse.",
  ui_story_5009_50090901_75_dialog_content = "O que é que foi isso, PlayerName?",
  ui_story_5009_50090901_76_dialog_content = "Senti o Aurorian que estava no cemitério.",
  ui_story_5009_50090901_77_dialog_content = "O Aurorian dessa última batalha…",
  ui_story_5009_50090901_78_dialog_content = "Exato! Aquela grande explosão de energia deve ser desse mesmo Aurorian!",
  ui_story_5009_50090901_79_dialog_content = "Ele penetrou a barreira dimensional e atingiu o Mirren.",
  ui_story_5009_50090901_80_dialog_content = "Nunca vi uma ofensiva assim. Aquele Aurorian tem poderes de ocultação e destruição terríveis!",
  ui_story_5009_50090901_81_dialog_content = "Você também nunca viu uma Luminática como essa?",
  ui_story_5009_50090901_82_dialog_content = "Hehe, não acredito que Vossa Alteza Carleen me elogiou!",
  ui_story_5009_50090901_83_dialog_content = "Quem é você?",
  ui_story_5009_50090901_84_dialog_content = "*Cof*... Imaginei que fosse você.",
  ui_story_5009_50090901_85_dialog_content = "Permita-me apresentá-la. Esta senhora é da Igreja de Lumópolis...",
  ui_story_5009_50090901_86_dialog_content = "Não, espere. Na verdade, é da True Order, Paloma Py...",
  ui_story_5009_50090901_87_dialog_content = "Paloma Pyrrhus? Da Casa de Pyrrhus?",
  ui_story_5009_50090901_88_dialog_content = "Você certamente é astuta e observadora, Vossa Alteza!",
  ui_story_5009_50090901_89_dialog_content = "Não acha emocionante ver dois procurados de duas casas rebeldes em um único dia?",
  ui_story_5009_50090901_90_dialog_content = "Você é Paloma Pyrrhus? Como pode ser uma Pyrrhus? Pensei que a Caroline...",
  ui_story_5009_50090901_91_dialog_content = "Pode me chamar de Paloma, Vossa Alteza.",
  ui_story_5009_50090901_92_dialog_content = "É você, Paloma! Você mudou bastante.",
  ui_story_5009_50090901_93_dialog_content = "Tá bom, isso tá ficando muito confuso...",
  ui_story_5009_50090901_94_dialog_content = "Casa de Pirro e Casa de Gautier são co-conspiradores, PlayerName, que faz Paloma aqui...",
  ui_story_5009_50090901_95_dialog_content = "Não nos esqueçamos, Vossa Alteza…",
  ui_story_5009_50090901_96_dialog_content = "A Paloma aqui não só é membro da rebelde Casa Pyrrhus, mas uma ex-freira que voltou as costas à Luz.",
  ui_story_5009_50090901_97_dialog_content = "Se não me engano, ela está na sua tal lista negra de procurados também, não? Não deveriam prendê-la, guerreiros da justiça?",
  ui_story_5009_50090901_98_dialog_content = "Como Lumópolis aplica suas leis não é da sua conta.",
  ui_story_5009_50090901_99_dialog_content = "É uma chatice ouvir todos vocês brigarem.",
  ui_story_5009_50090901_100_dialog_content = "Mirren Gautier deve morrer. Nada mais me importa.",
  ui_story_5009_50090901_101_dialog_content = "Eu sabia que o Mirren tinha começado tudo isso!",
  ui_story_5009_50090901_102_dialog_content = "Mas como a Casa Pyrrhuss se envolveu nisso?",
  ui_story_5009_50090901_103_dialog_content = "Pode continuar seu inquérito como quiser, Vossa Alteza.",
  ui_story_5009_50090901_104_dialog_content = "Mas estou aqui por vingança, não casos jurídicos.",
  ui_story_5009_50090901_105_dialog_content = "Ah, é tão tocante quando velhos amigos se reúnem.",
  ui_story_5009_50090901_106_dialog_content = "Quantas vezes preciso te dizer, Paloma, que as autoridades em Lumópolis são aqueles que mataram nosso povo?!",
  ui_story_5009_50090901_107_dialog_content = "Você deveria estar atrás da arrogante e convencida Carleen Schwartz!",
  ui_story_5009_50090901_108_dialog_content = "Claro, a ilustre juíza também.",
  ui_story_5009_50090901_109_dialog_content = "Parece que temos concepções diferentes da palavra líder.",
  ui_story_5009_50090901_110_dialog_content = "Mas enfim, não se pode esperar que um Eclipsita entenda a linguagem Aurorian.",
  ui_story_5009_50090901_111_dialog_content = "Não se oponha a mim!",
  ui_story_5009_50090901_112_dialog_content = "Essa é sua última chance.",
  ui_story_5009_50090901_113_dialog_content = "Exija a vingança contra Lumópolis comigo, ou morra ao lado deles. Escolha.",
  ui_story_5009_50090901_114_dialog_content = "Vejo que só a morte pode curar sua tagarelice.",
  ui_story_5009_50090901_115_dialog_content = "Curar? Na verdade isso me lembrou do fato de que não preciso te matar…",
  ui_story_5009_50090901_116_dialog_content = "O grande mestre ficaria encantado se lhe desse um novo brinquedo.",
  ui_story_5009_50090901_117_dialog_content = "Uma bela e poderosa Aurorian.",
  ui_story_5009_50090901_118_dialog_content = "Hmm. Quero ver você tentar.",
  ui_story_5009_50090901_119_dialog_content = "O que tá acontecendo aqui? A Paloma vai nos ajudar a lutar?",
  ui_story_5009_50090901_120_dialog_content = "Ela é poderosa. Talvez Mirren não ganhe.",
  ui_story_5009_50090901_121_dialog_content = "Paloma está no topo da lista dos mais perigosos da igreja. Ela se voltou completamente contra a Luz para se juntar à True Order.",
  ui_story_5009_50090901_122_dialog_content = "A True Order... Parece que a Paloma aprendeu Lumináticas especiais com eles.",
  ui_story_5009_50090901_123_dialog_content = "E uma Luminática que não foi afetada pelo eclipse e era poderosa o suficiente para quebrar a barreira dimensional.",
  ui_story_5009_50090901_124_dialog_content = "Espera, acho que a conversa entre Paloma e aquele Eclipsita é sobre...",
  ui_story_5009_50090901_125_dialog_content = "Ei, você vai parar de falar ou o quê?",
  ui_story_5009_50090901_126_dialog_content = "O Mirren tem reforços chegando, e eu não tô aqui pra ser guarda-costas!",
  ui_story_5009_50090901_127_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_5009_50090901_128_dialog_content = "Isso é ruim, tô sentindo Eclipsitas se aproximando de nós...",
  ui_story_5009_50090901_129_dialog_content = "Tudo bem, nossos reforços também chegaram!",
  ui_story_5009_50090901_130_dialog_content = "Você ainda pode coordenar, PlayerName?",
  ui_story_5009_50090901_131_dialog_content = "Deixa comigo!",
  ui_story_5009_50090902_1_dialog_content = "Vamos mesmo lutar, Lady Pyrrhus?",
  ui_story_5009_50090902_2_dialog_content = "Repetindo as palavras, Sr. Gautier?",
  ui_story_5009_50090902_3_dialog_content = "Agora é diferente, já que dois traidores de Lumópolis estão lutando perante suas autoridades.",
  ui_story_5009_50090902_4_dialog_content = "Quem você acha que vai ganhar com isso?",
  ui_story_5009_50090902_5_dialog_content = "Tenho tempo de sobra para pensar nisso depois que você morrer.",
  ui_story_5009_50090902_6_dialog_content = "Enfraquecemos um ao outro para que eles imponham a \"justiça\" no final. Excelente.",
  ui_story_5009_50090902_7_dialog_content = "Se morrermos, esse seria o fim da linhagem dos Gautier e Pyrrhus!",
  ui_story_5009_50090902_8_dialog_content = "Nós dois provamos da justiça de Lumópolis, Paloma.",
  ui_story_5009_50090902_9_dialog_content = "Os atos da Casa Pyrrhus trouxeram vergonha para Lumópolis. Por favor, nos perdoe, Deus da Luz.",
  ui_story_5009_50090902_10_dialog_content = "Estamos dispostos a aceitar a punição em troca do seu perdão.",
  ui_story_5009_50090902_11_dialog_content = "A dor de perder os poderes Lúmina deve sempre servir como um lembrete para não cometer maldades...",
  ui_story_5009_50090902_12_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5009_50090902_13_dialog_content = "Alguém quer sair do Assentamento 14? Sou mensageiro de Lumópolis.",
  ui_story_5009_50090902_14_dialog_content = "Abra a porta e aceite, Paloma.",
  ui_story_5009_50090902_15_dialog_content = "Claro, pai.",
  ui_story_5009_50090902_16_dialog_content = "<color=#828282>Crec...</color>",
  ui_story_5009_50090902_17_dialog_content = "A vida na Baixa Lumópolis tem sido difícil nos últimos anos. Todos sofremos…",
  ui_story_5009_50090902_18_dialog_content = "É tudo culpa deles, então por que temos que sofrer também?",
  ui_story_5009_50090902_19_dialog_content = "Eu não me importaria se fôssemos só nós, mas nossa filha…",
  ui_story_5009_50090902_20_dialog_content = "E daí? O pior que pode nos acontecer é sair da igreja, perder os poderes de Lúmina e viver como plebeus.",
  ui_story_5009_50090902_21_dialog_content = "Mas sequestrar os filhos de Gautier pra transformação é um pecado, não uma contravenção.",
  ui_story_5009_50090902_22_dialog_content = "Mas… Mas o que isso tem a ver conosco?",
  ui_story_5009_50090902_23_dialog_content = "Os Schwartz nunca ligaram para os outros nobres.",
  ui_story_5009_50090902_24_dialog_content = "Silêncio!",
  ui_story_5009_50090902_25_dialog_content = "Você ao menos sabe que os Gautier inocentes foram banidos para a Baixa Lumópolis?",
  ui_story_5009_50090902_26_dialog_content = "O quê? Do que está falando?",
  ui_story_5009_50090902_27_dialog_content = "Aceite o seu destino. Fique feliz por ainda termos vida.",
  ui_story_5009_50090902_28_dialog_content = "...",
  ui_story_5009_50090902_29_dialog_content = "Pai, mãe, vocês conhecem Mirren Gautier?",
  ui_story_5009_50090902_30_dialog_content = "Mirren?",
  ui_story_5009_50090902_31_dialog_content = "Não é um pintor renomado da Casa Gautier?",
  ui_story_5009_50090902_32_dialog_content = "Por que pergunta, Paloma?",
  ui_story_5009_50090902_33_dialog_content = "Este é um aviso que acabamos de receber da Corte de Justiça. Diz que Mirren Gautier é um elemento perigoso.",
  ui_story_5009_50090902_34_dialog_content = "Caso veja essa pessoa, avise as autoridades imediatamente.",
  ui_story_5009_50090902_35_dialog_content = "Sério? Seu tio falou sobre ele comigo há alguns dias.",
  ui_story_5009_50090902_36_dialog_content = "Meu irmão também falou de Mirren numa conversa ontem.",
  ui_story_5009_50090902_37_dialog_content = "Estou com um mau pressentimento. Devemos ir com calma.",
  ui_story_5009_50090902_38_dialog_content = "Tá bom, pai…",
  ui_story_5009_50090902_39_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5009_50090902_40_dialog_content = "Depressa, depressa…",
  ui_story_5009_50090902_41_dialog_content = "Corra, o Exército de Lumópolis cercou o assentamento!",
  ui_story_5009_50090902_42_dialog_content = "O quê?",
  ui_story_5009_50090902_43_dialog_content = "Se acalma, relaxa!",
  ui_story_5009_50090902_44_dialog_content = "Mirren Gautier está usurpando. O exército e a igreja estão marchando!",
  ui_story_5009_50090902_45_dialog_content = "A Casa de Gautier? Usurpando?",
  ui_story_5009_50090902_46_dialog_content = "A igreja? Por que a igreja reagiria?",
  ui_story_5009_50090902_47_dialog_content = "Mirren parece ter usado a transformação, e os Pyrrhus e os Eclipsitas estão envolvidos na insurreição.",
  ui_story_5009_50090902_48_dialog_content = "Preciso ir. Façam o mesmo.",
  ui_story_5009_50090902_49_dialog_content = "E isso acaba nos envolvendo, de novo!",
  ui_story_5009_50090902_50_dialog_content = "Se eu conheço bem Lumópolis, isso vai se tornar uma grande perseguição.",
  ui_story_5009_50090902_51_dialog_content = "Como um Pyrrhus, não precisamos nos preocupar desde que sejamos julgados com justiça.",
  ui_story_5009_50090902_52_dialog_content = "Você é muito idealista, criança…",
  ui_story_5009_50090902_53_dialog_content = "Me ouça e se esconda. Eu vou lá ver com a sua mãe.",
  ui_story_5009_50090902_54_dialog_content = "Venha, Paloma. Ninguém escapará se continuarmos esperando.",
  ui_story_5009_50090902_55_dialog_content = "Vai!",
  ui_story_5009_50090902_56_dialog_content = "Pelo decreto do Senhor, morte aos traidores! Pelo decreto do Senhor, morte aos traidores!",
  ui_story_5009_50090902_57_dialog_content = "Por que eles estão lutando e de onde esses monstros vieram?",
  ui_story_5009_50090902_58_dialog_content = "Hã? São o nosso povo! Os Eclipsitas… Eles foram transformados em Eclipsitas!",
  ui_story_5009_50090902_59_dialog_content = "Já era… É o fim dos Pyrrhus.",
  ui_story_5009_50090902_60_dialog_content = "Punição aos rebeldes! Punição aos rebeldes! Punição aos rebeldes!",
  ui_story_5009_50090902_62_dialog_content = "A justiça de Lumópolis… Haha! Tenho muita experiência com ela também.",
  ui_story_5009_50090902_63_dialog_content = "*Cof* Então… cancele o ataque…",
  ui_story_5009_50090902_64_dialog_content = "A origem de tudo deve vir de Lumópolis…",
  ui_story_5009_50090902_65_dialog_content = "Muito bem, Mirren Gautier. Assim que você morrer, vou dar um jeito de mandar o prefeito pra te fazer companhia.",
  ui_story_5009_50090902_66_dialog_content = "Mas uma coisa de cada vez… Chegou a sua hora.",
  ui_story_5009_50090902_67_dialog_content = "Senhorita Paloma Pyrrhus… Se o fim for esse, tudo que posso fazer é enterrá-la dignamente, como esses guerreiros honrosos.",
  ui_story_5009_50090902_68_dialog_content = "Quanto drama…",
  ui_story_5009_50091001_1_dialog_content = "Droga… Minha habilidade psíquica ainda não se recuperou totalmente…",
  ui_story_5009_50091001_2_dialog_content = "Está bem, PlayerName! Seus comandos ainda eram precisos agora!",
  ui_story_5009_50091001_3_dialog_content = "E o monstro? Pra onde ele foi?",
  ui_story_5009_50091001_4_dialog_content = "Ainda tá perto! Mas seu poder parece estar… aumentando?",
  ui_story_5009_50091001_5_dialog_content = "Mas o ataque de Paloma o feriu muito! Todos presenciamos! A não ser…",
  ui_story_5009_50091001_6_dialog_content = "Parece estar devorando os Eclipsitas próximos para recuperar o Fluxo Escuro.",
  ui_story_5009_50091001_7_dialog_content = "Ah… De novo não! É nojento!",
  ui_story_5009_50091001_8_dialog_content = "Você ouviu isso, Paloma?",
  ui_story_5009_50091001_9_dialog_content = "O monstro ainda está em algum lugar por perto! Mantenha a guarda!",
  ui_story_5009_50091001_10_dialog_content = "Cuidem de si, e fiquem fora do meu caminho.",
  ui_story_5009_50091001_11_dialog_content = "Uma onda de Fluxo Escuro!",
  ui_story_5009_50091001_12_dialog_content = "Ah, não, tá vindo da direção da Paloma! O monstro tá pronto pra atacar!",
  ui_story_5009_50091001_13_dialog_content = "Isso é péssimo…",
  ui_story_5009_50091001_14_option_content = "Aumento de Força",
  ui_story_5009_50091001_15_dialog_content = "Paloma! Desvie pra esquerda!",
  ui_story_5009_50091001_16_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5009_50091001_17_dialog_content = "Você… Você tá bem, Paloma?",
  ui_story_5009_50091001_18_dialog_content = "*Cof, cof* Esse é… o poder dos Celestitas?",
  ui_story_5009_50091001_19_dialog_content = "Instantaneamente transmitindo pensamentos para minha mente…",
  ui_story_5009_50091001_20_dialog_content = "Não é melhor pedir permissão antes?",
  ui_story_5009_50091001_21_dialog_content = "Se não fosse por PlayerName forçou o poder para ajudá-lo a se esquivar...",
  ui_story_5009_50091001_22_dialog_content = "A emboscada de Mirren teria dado certo.",
  ui_story_5009_50091001_23_dialog_content = "Mirren… fica à espreita e ataca como um rato.",
  ui_story_5009_50091001_24_dialog_content = "Hahaha! Eu gostei da sua conduta, senhorita Illumina!",
  ui_story_5009_50091001_25_dialog_content = "Estou bem. Não se preocupe comigo.",
  ui_story_5009_50091001_26_dialog_content = "Temos que fazer de tudo para encontrá-lo, antes que ele fuja!",
  ui_story_5009_50091001_27_dialog_content = "Se não puder atacar, fuja. Esse sempre foi o estilo de Mirren Gautier.",
  ui_story_5009_50091001_28_dialog_content = "Você parece o conhecer bem, Paloma.",
  ui_story_5009_50091001_29_dialog_content = "Afe… Tudo que sei sobre ele é sua conduta covarde em combate.",
  ui_story_5009_50091002_1_dialog_content = "As famílias Gautier e Pyrrhus se rebelaram contra as autoridades e conspiraram com os Eclipsitas! Nunca esqueçam da traição deles!",
  ui_story_5009_50091002_2_dialog_content = "Punição aos rebeldes! Morte aos Eclipsitas!",
  ui_story_5009_50091002_3_dialog_content = "Pessoal, por favor! Nós apenas fazemos parte da família Pyrrhus! Entendam isso!",
  ui_story_5009_50091002_4_dialog_content = "A sua família é de rebeldes traidores, que ousam conspirar com os Eclipsitas e usar as técnicas deles! Vocês não merecem misericórdia!",
  ui_story_5009_50091002_5_dialog_content = "Se isso tem a ver com os experimentos com cristal… Nós já fomos punidos por isso, meu senhor!",
  ui_story_5009_50091002_6_dialog_content = "Fomos privados de Lúmina e mandados para a Baixa Lumópolis…",
  ui_story_5009_50091002_7_dialog_content = "Rezamos ao Deus da Luz todos os dias, pedindo perdão… Eu juro que é verdade!",
  ui_story_5009_50091002_8_dialog_content = "Aqueles transformados em Eclipsitas agora... Eram membros da família Pyrrhus!",
  ui_story_5009_50091002_9_dialog_content = "Nós… não somos como eles…",
  ui_story_5009_50091002_10_dialog_content = "Não fomos transformados!",
  ui_story_5009_50091002_A1_dialog_content = "Vocês são culpados, todos vocês são! Peguem-nos!",
  ui_story_5009_50091002_11_dialog_content = "Pai! Mãe! O que está acontecendo?",
  ui_story_5009_50091002_12_dialog_content = "Paloma?! Fuja, Paloma! Corre daqui!!",
  ui_story_5009_50091002_13_dialog_content = "Pai? Mãe!",
  ui_story_5009_50091002_14_dialog_content = "Paloma… Vem comigo! Depressa!",
  ui_story_5009_50091002_15_dialog_content = "Ugh...",
  ui_story_5009_50091002_16_dialog_content = "Fica longa dela!",
  ui_story_5009_50091002_17_dialog_content = "Tá brava, mulher?! Como ousa me morder!",
  ui_story_5009_50091002_18_dialog_content = "Vocês! Vão atrás da garota!",
  ui_story_5009_50091002_19_dialog_content = "Sim, senhor!",
  ui_story_5009_50091002_20_dialog_content = "Paloma, por favor… Você tem que comer algo.",
  ui_story_5009_50091002_21_dialog_content = "Por quê? O que é tudo isso?",
  ui_story_5009_50091002_22_dialog_content = "Papai… Mamãe… Eles vão ficar bem?",
  ui_story_5009_50091002_23_dialog_content = "Faz três dias, Paloma. Você precisa descansar.",
  ui_story_5009_50091002_24_dialog_content = "Ah.. Você voltou finalmente. Descobriu alguma coisa sobre meus pais?",
  ui_story_5009_50091002_25_dialog_content = "Eu só soube coisas ruins. Se quiser ouvir, é melhor se preparar mentalmente.",
  ui_story_5009_50091002_26_dialog_content = "Nossos familiares foram massacrados pelo exército de Lumópolis junto com…",
  ui_story_5009_50091002_27_dialog_content = "......",
  ui_story_5009_50091002_28_dialog_content = "Certamente, você entende o que estou tentando lhe dizer… Certo?",
  ui_story_5009_50091002_29_dialog_content = "Eu não sei onde Mirren Gautier aprendeu aquelas técnicas de transformação, mas ele sequestrou vários parentes nossos e realizou experimentos com eles.",
  ui_story_5009_50091002_30_dialog_content = "Logo depois, a família Gautier começou a rebelião.",
  ui_story_5009_50091002_31_dialog_content = "Eles transformaram… nossos familiares? Eles estavam se vingando da família Pyrrhus?",
  ui_story_5009_50091002_32_dialog_content = "Não completamente. Eles acreditam que são as vítimas e que eles foram todos exilados por conta da falta de julgamento apropriado de Lumópolis.",
  ui_story_5009_50091002_33_dialog_content = "Eu creio que a hostilidade deles em relação à nobreza de Lumópolis tenha afetado e muito a rebelião.",
  ui_story_5009_50091002_34_dialog_content = "De todo modo, este massacre foi outro caso da punição indiscriminada de Lumópolis. Para os nobres, esta é a resposta para o problema deles.",
  ui_story_5009_50091002_35_dialog_content = "Então não há verdade ou justiça de verdade?",
  ui_story_5009_50091002_36_dialog_content = "A verdade é… muito mais complicada e mancharia a reputação da nobreza.",
  ui_story_5009_50091002_37_dialog_content = "Quanto à justiça? Bom… Nossa família foi inteiramente apagada. Para forasteiros, essa é a justiça.",
  ui_story_5009_50091002_38_dialog_content = "E a gente? Somos inocentes!",
  ui_story_5009_50091002_39_dialog_content = "As forças do destino quiseram nos deixar vivos. Pensar demais nisso não vai ajudar em nada.",
  ui_story_5009_50091002_40_dialog_content = "Não… Isso não está certo. Isso não pode ser… não pode ser justiça.",
  ui_story_5009_50091002_41_dialog_content = "O mais irônico é que apesar das famílias Gautier e Pyrrhus terem sido exterminadas, Mirren ainda parece estar livre. Eles não conseguem chegar nele.",
  ui_story_5009_50091002_42_dialog_content = "Mirren Gautier… Ele não é muito mais velho do que você.",
  ui_story_5009_50091002_43_dialog_content = "Ele era só um garoto que adorava desenhar… Não entendo como ele obteve tanto conhecimento.",
  ui_story_5009_50091002_44_dialog_content = "Ele ainda não morreu? Ótimo… Já sei o que tenho que fazer.",
  ui_story_5009_50091002_45_dialog_content = "Bem, pense nos seus pais. Tenho certeza de que eles te desejam uma vida feliz.",
  ui_story_5009_50091002_46_dialog_content = "Mãe… Pai…",
  ui_story_5009_50091002_47_dialog_content = "Já se esqueceu? Você não consegue derrotar nem o mais novato dos guardas.",
  ui_story_5009_50091002_48_dialog_content = "Quer dizer, sem Luminática, não consigo nem…",
  ui_story_5009_50091002_49_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5009_50091002_50_dialog_content = "Punição aos rebeldes! Morte aos Eclipsitas!",
  ui_story_5009_50091002_51_dialog_content = "Este lugar está escondendo fugitivos da família Pyrrhus! Atrás deles!",
  ui_story_5009_50091002_52_dialog_content = "Corra, Paloma!",
  ui_story_5009_50091002_53_dialog_content = "Não sem você!",
  ui_story_5009_50091002_54_dialog_content = "Você tem que sobreviver, Paloma! Pra nos vingar… Você tem que sobreviver!",
  ui_story_5009_50091101_1_dialog_content = "Não baixem a guarda, pessoal! Fiquem alertas!",
  ui_story_5009_50091101_2_dialog_content = "Mas não sinto nenhum Eclipsita por perto…",
  ui_story_5009_50091101_3_dialog_content = "Tudo bem… Ele só tá pedindo pra todos terem cuidado comigo.",
  ui_story_5009_50091101_4_dialog_content = "Afinal, sou uma fugitiva dos traidores da família Pyrrhus e membro da blasfemadora True Order. Ao que parece, sou muito perigosa e não sou de confiança.",
  ui_story_5009_50091101_5_dialog_content = "Se você tivesse más intenções, já poderia ter nos matado com os seus poderes destrutivos e nem teríamos visto.",
  ui_story_5009_50091101_6_dialog_content = "Certo, já chega. Vamos procurar Mirren!",
  ui_story_5009_50091101_7_dialog_content = "O Eclipse ainda não terminou, então ele deve estar por perto.",
  ui_story_5009_50091101_8_dialog_content = "Vou tentar senti-lo de novo.",
  ui_story_5009_50091101_9_dialog_content = "Você não precisa se esforçar demais, PlayerName.",
  ui_story_5009_50091101_10_dialog_content = "Relaxa, Vice. Está tudo sob controle.",
  ui_story_5009_50091101_11_dialog_content = "Se o encontrar, terei como acabar com ele.",
  ui_story_5009_50091101_12_option_content = "Sentir",
  ui_story_5009_50091101_13_dialog_content = "Paloma! Corra!",
  ui_story_5009_50091101_A2_dialog_content = "Corra!",
  ui_story_5009_50091101_14_dialog_content = "Pai? Mãe!",
  ui_story_5009_50091101_A1_dialog_content = "Paloma… Vem comigo! Depressa!",
  ui_story_5009_50091101_15_dialog_content = "Ugh...",
  ui_story_5009_50091101_16_dialog_content = "Fica longa dela!",
  ui_story_5009_50091101_17_dialog_content = "Tá brava, mulher?! Como ousa me morder!",
  ui_story_5009_50091101_18_dialog_content = "P… Paloma…",
  ui_story_5009_50091101_19_dialog_content = "Hã? Por que está me olhando?",
  ui_story_5009_50091101_20_dialog_content = "Ah… Acho que seus sentimentos fortes tão interferindo na minha habilidade psíquica.",
  ui_story_5009_50091101_21_dialog_content = "Hunf.",
  ui_story_5009_50091101_22_dialog_content = "Eu vou me afastar para que minhas fortes emoções não interfiram.",
  ui_story_5009_50091101_23_dialog_content = "Fortes emoções? Parece que o ódio da Paloma por Mirren deve ser bem forte.",
  ui_story_5009_50091101_24_dialog_content = "Apesar da Paloma falar pouco, eu acredito ter finalmente entendido.",
  ui_story_5009_50091101_25_dialog_content = "Se Mirren for mesmo o responsável por toda essa rixa, vai fazer todo o sentido.",
  ui_story_5009_50091101_26_dialog_content = "Ah?",
  ui_story_5009_50091101_27_dialog_content = "Lady Carleen, a família Pyrrhus foi a responsável pelo incidente com Beryl.",
  ui_story_5009_50091101_28_dialog_content = "Por isso, a família Gautier achava que tinha sido injustamente exilada como consequência das ações da família Pyrrhus.",
  ui_story_5009_50091101_29_dialog_content = "Para se vingar, Mirren orquestrou a rebelião da família Gautier.",
  ui_story_5009_50091101_30_dialog_content = "Para Paloma e seus familiares, o massacre das duas famílias como resultado da trama de Mirren também é uma injustiça.",
  ui_story_5009_50091101_31_dialog_content = "Portanto, a rixa entre as duas famílias não é nada simples.",
  ui_story_5009_50091101_32_dialog_content = "E Paloma nunca perdoaria Mirren, que foi a causa direta da morte de sua família.",
  ui_story_5009_50091101_33_dialog_content = "Espere um pouco… Isso tudo não é culpa da autoridade de Lumópolis que não fez um julgamento justo?",
  ui_story_5009_50091101_34_dialog_content = "...",
  ui_story_5009_50091101_35_dialog_content = "Ainda há vários detalhes para se esclarecer. Fique tranquila, Lady Carleen, vou continuar investigando com toda a minha habilidade.",
  ui_story_5009_50091101_36_dialog_content = "Uma coisa que eu não entendo é como Mirren e Paloma possuem um poder tão incrível.",
  ui_story_5009_50091101_37_dialog_content = "Eu tô aqui, sabia?",
  ui_story_5009_50091101_38_dialog_content = "É tão estranho assim eu ser tão poderosa, considerando que eu me rebaixei tanto a ponto de entrar para a True Order?",
  ui_story_5009_50091101_39_dialog_content = "Quanto a Mirren, até onde eu descobri, o poder dele tem algo a ver com aquela organização misteriosa…",
  ui_story_5009_50091101_40_dialog_content = "Foi o que pensei, senhorita Paloma.",
  ui_story_5009_50091101_41_dialog_content = "Mesmo os acontecimentos de dezessete anos atrás, e tudo que decorreu até hoje podem ser atribuído a…",
  ui_story_5009_50091101_42_dialog_content = "Não meça palavras deste jeito. Vocês estão falando do Eclipse, não é?",
  ui_story_5009_50091101_43_dialog_content = "Já lutamos com eles antes. Você poderia dizer que somos velhos conhecidos agora, certo? PlayerName?",
  ui_story_5009_50091101_44_dialog_content = "Espere...",
  ui_story_5009_50091101_45_dialog_content = "Eu tô sentindo algo! Mirren ainda não fugiu de Eraveil!",
  ui_story_5009_50091101_46_dialog_content = "Tem uma caverna subterrânea… Muitos Eclipsitas de alto nível estão adormecidos lá!",
  ui_story_5009_50091101_47_dialog_content = "O que ele planeja fazer lá?",
  ui_story_5009_50091101_48_dialog_content = "Não é óbvio? Comer os Eclipsitas e recuperar o Fluxo Escuro.",
  ui_story_5009_50091101_49_dialog_content = "Não podemos permitir isso…",
  ui_story_5009_50091101_50_dialog_content = "PlayerName! Me dê uma direção!",
  ui_story_5009_50091101_51_dialog_content = "Em algum lugar por ali.",
  ui_story_5009_50091101_52_dialog_content = "Você ainda consegue usar essas poderosas habilidades psíquicas em Eclipse… Impressionante.",
  ui_story_5009_50091101_53_dialog_content = "Mirren Gautier… Me espere.",
  ui_story_5009_50091101_54_dialog_content = "Quer dizer que vai sozinha, Paloma?",
  ui_story_5009_50091101_55_dialog_content = "Por que não descansa um pouco antes? Podemos pegá-lo juntos assim que recuperarmos nossas forças!",
  ui_story_5009_50091101_56_dialog_content = "Hã? Eu acabei de te elogiar, e agora você acha que pode me dar ordens?",
  ui_story_5009_50091101_57_dialog_content = "Espere, Paloma!",
  ui_story_5009_50091101_58_dialog_content = "Ela foi embora…",
  ui_story_5009_50091101_59_dialog_content = "Com um poder como o dela, ela é mais do que qualificada pra lutar sozinha.",
  ui_story_5009_50091101_60_dialog_content = "Ainda assim, ela gastou muita força agora. Se Mirren conseguiu recuperar o Fluxo Escuro…",
  ui_story_5009_50091101_61_dialog_content = "Eu acho que ela não tem chance de vencer.",
  ui_story_5009_50091101_62_dialog_content = "Temos que nos apressar e encontrá-la.",
  ui_story_5009_50091101_63_dialog_content = "Mais um obstáculo no caminho, né?",
  ui_story_5009_50091101_64_dialog_content = "Vamos nessa!",
  ui_story_5009_50091202_1_dialog_content = "Está dizendo que você conhece a Paloma há bastante tempo?",
  ui_story_5009_50091202_2_dialog_content = "Sim… Na época, ela era só uma garotinha quieta, tímida e indefesa.",
  ui_story_5009_50091202_3_dialog_content = "Quieta, tímida… e indefesa?",
  ui_story_5009_50091202_4_dialog_content = "Ainda estamos falando da mesma Paloma?",
  ui_story_5009_50091202_5_dialog_content = "Nos conhecemos na Academia Matinal, muitos anos atrás.",
  ui_story_5009_50091202_6_dialog_content = "Na época, eu tinha certeza de que ela se tornaria uma freira maravilhosa, mas, então…",
  ui_story_5009_50091202_7_dialog_content = "Eu vi o nome dela na lista dos fugitivos.",
  ui_story_5009_50091202_8_dialog_content = "Pelos crimes de rebelião familiar e de traição à igreja…",
  ui_story_5009_50091202_9_dialog_content = "A família Pyrrhus, junto com a família Gautier, montaram uma rebelião violenta…",
  ui_story_5009_50091202_10_dialog_content = "Se ela não tivesse fugido, Paloma seria executada por Lumópolis?",
  ui_story_5009_50091202_11_dialog_content = "Como o resto da família dela?",
  ui_story_5009_50091202_12_dialog_content = "......",
  ui_story_5009_50091202_13_dialog_content = "Eu acho que… entendo ela agora.",
  ui_story_5009_50091202_14_dialog_content = "Por ser a única sobrevivente da família e procurar uma explicação a respeito disso…",
  ui_story_5009_50091202_15_dialog_content = "Eu sei o que ela tá sentindo.",
  ui_story_5009_50091202_16_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5009_50091202_17_dialog_content = "Ela quer descobrir a verdade, procurar o culpado e se vingar em nome da família…",
  ui_story_5009_50091202_18_dialog_content = "Você deve se sentir de maneira semelhante, PlayerName.",
  ui_story_5009_50091202_19_dialog_content = "É mais do que isso, bem mais.",
  ui_story_5009_50091202_20_dialog_content = "Vocês não pensaram nisso? Se não tivesse alguém para impedir essas pessoas ou melhorar a situação…",
  ui_story_5009_50091202_21_dialog_content = "Essas tragédias estariam fadadas a se repetir, várias e várias vezes…",
  ui_story_5009_50091202_22_dialog_content = "É mesmo. Portanto, temos que investigar o passado deles com cuidado e encontrar a causa verdadeira desta guerra. Só assim vamos impedir que isso ocorra de novo.",
  ui_story_5009_50091202_23_dialog_content = "Mas se o problema está na nobreza de Lumópolis… Como podemos resolver?",
  ui_story_5009_50091202_24_dialog_content = "Podemos responder a esta pergunta outra hora. Agora, Mirren é nossa prioridade.",
  ui_story_5009_50091202_25_dialog_content = "Aqui!",
  ui_story_5009_50091202_26_dialog_content = "Eu tenho certeza disso… Mirren está aqui!",
  ui_story_5009_50091202_27_dialog_content = "Espera? Que som é esse?",
  ui_story_5009_50091202_28_dialog_content = "<color=#e8d9bb>Estrondo...!</color>",
  ui_story_5009_50091202_29_dialog_content = "Cuidado onde pisam, pessoal!",
  ui_story_5009_50091202_30_dialog_content = "O terremoto parou…",
  ui_story_5009_50091202_31_dialog_content = "Como essas estruturas subterrâneas foram tão bem construídas a ponto de aguentarem um tremor desses?",
  ui_story_5009_50091202_32_dialog_content = "Se é uma caverna natural, acho que estamos presos aqui dentro.",
  ui_story_5009_50091202_33_dialog_content = "Que barulho foi esse?",
  ui_story_5009_50091202_34_dialog_content = "Vem de dentro das estruturas!",
  ui_story_5009_50091202_35_dialog_content = "PlayerName... Poderia ser...?",
  ui_story_5009_50091202_36_dialog_content = "É… Eu tô sentindo a Paloma. É provável…",
  ui_story_5009_50091202_37_dialog_content = "Que Paloma já tenha encontrado Mirren.",
  ui_story_5009_50091301_A1_dialog_content = "Hummm… Poder! Poder delicioso!",
  ui_story_5009_50091301_1_dialog_content = "<color=#e8d9bb>Estrondo...!</color>",
  ui_story_5009_50091301_A2_dialog_content = "Hahaha! Bem a tempo.",
  ui_story_5009_50091301_2_dialog_content = "Mirren Gautier… Você não passa de um verme covarde que se esconde.",
  ui_story_5009_50091301_3_dialog_content = "É? Mas você não tem nem chance de ser um verme!",
  ui_story_5009_50091301_4_dialog_content = "Ai...!",
  ui_story_5009_50091301_5_dialog_content = "Aceite como um elogio meu, é impressionante… que você aguente lutar até aqui.",
  ui_story_5009_50091301_6_dialog_content = "Mas as técnicas ocultas da True Order não passam de Lumináticas de baixo nível.",
  ui_story_5009_50091301_7_dialog_content = "Não são como meu poder… Um poder extraordinário concedido a mim pelo meu mestre.",
  ui_story_5009_50091301_8_dialog_content = "Err… Esse poder que você tá falando… Só pode ser recuperado dessa forma tão repugnante?",
  ui_story_5009_50091301_9_dialog_content = "Depois de se transformar num monstro você também perdeu o paladar?",
  ui_story_5009_50091301_10_dialog_content = "Caso contrário, não sei como você conseguiria comer tantos Eclipsitas idiotas.",
  ui_story_5009_50091301_11_dialog_content = "Ah! Parece que você ainda precisa entender isso, mas a coisa mais deliciosa do mundo… é o poder!",
  ui_story_5009_50091301_12_dialog_content = "Quer provar? Ah claro, saquei...",
  ui_story_5009_50091301_13_dialog_content = "Se você consumisse Fluxo Escuro, ficaria ainda mais atraente do que já é...",
  ui_story_5009_50091301_14_dialog_content = "Acha mesmo que todo mundo é como você?",
  ui_story_5009_50091301_15_dialog_content = "Ah, só queria te dar a oportunidade de expressar o que você poderia ser...",
  ui_story_5009_50091301_16_dialog_content = "Mas suponho que seria mais fácil juntar seus restos mortais e criar um espécime com eles!",
  ui_story_5009_50091301_17_dialog_content = "Veja, é o Mirren!",
  ui_story_5009_50091301_18_dialog_content = "Essa não... Paloma, cuidado!",
  ui_story_5009_50091301_19_option_content = "Aumento de Força",
  ui_story_5009_50091301_20_dialog_content = "Esquiva para trás!",
  ui_story_5009_50091301_21_dialog_content = "Ainda bem! Não achei que Paloma desviaria do último ataque!",
  ui_story_5009_50091301_22_dialog_content = "Mesmo assim, parece completamente exausta...",
  ui_story_5009_50091301_23_dialog_content = "*Tosse* PlayerName...",
  ui_story_5009_50091301_24_dialog_content = "Você nunca pede permissão antes de usar suas habilidades psíquicas?",
  ui_story_5009_50091301_25_option_content = "Na verdade não...",
  ui_story_5009_50091301_26_dialog_content = "Só uso esse poder em caso de emergência!",
  ui_story_5009_50091301_27_option_content = "Não tive escolha...",
  ui_story_5009_50091301_28_dialog_content = "Não tinha como pensar muito em uma situação extrema…",
  ui_story_5009_50091301_29_dialog_content = "Anh? Então devo me considerar sortuda.",
  ui_story_5009_50091301_30_dialog_content = "Por que demorou tanto? Perdeu uma bela apresentação agorinha mesmo, sabia?",
  ui_story_5009_50091301_31_dialog_content = "Suponho que não faça a menor diferença. Por que...",
  ui_story_5009_50091301_32_dialog_content = "O show para valer está prestes a começar!",
  ui_story_5009_50091301_33_dialog_content = "Cuidado, pessoal!",
  ui_story_5009_50091301_34_dialog_content = "Esse espaço estranho de novo não...",
  ui_story_5009_50091301_35_dialog_content = "Chegamos tarde demais? Parece que ele recuperou as forças. Não imagino quantos Eclipsitas comeu para se recuperar tão bem...",
  ui_story_5009_50091301_36_dialog_content = "Sai do meu caminho.",
  ui_story_5009_50091301_37_dialog_content = "<color=#e8d9bb>Wham! Wham! Wham!</color>",
  ui_story_5009_50091301_38_dialog_content = "Não consigo quebrar! Será que gastei tanto poder assim?",
  ui_story_5009_50091301_39_option_content = "Tente sentir.",
  ui_story_5009_50091301_40_dialog_content = "Vou tentar de novo...",
  ui_story_5009_50091301_41_option_content = "Aumento de Força!",
  ui_story_5009_50091301_42_dialog_content = "PlayerName...",
  ui_story_5009_50091301_43_dialog_content = "Suas habilidades psíquicas não adiantam muito dentro desse espaço.",
  ui_story_5009_50091301_44_dialog_content = "Espere, deixa eu pensar... Deve haver algo que eu possa fazer.",
  ui_story_5009_50091301_45_dialog_content = "Pessoal, cuidado com os ataques do inimigo!",
  ui_story_5009_50091301_46_dialog_content = "Shiu! Cala a boca...",
  ui_story_5009_50091301_47_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5009_50091301_48_dialog_content = "PlayerName! Você encontra uma maneira de sair daqui; Vou me defender dos ataques de Mirren!",
  ui_story_5009_50091301_49_dialog_content = "E-Entendi!",
  ui_story_5009_50091301_50_dialog_content = "Hahaha! Ah, Paloma... Jamais pensei que você seria tão ingênua depois de tudo que rolou.",
  ui_story_5009_50091301_51_dialog_content = "Tente evitar meus ataques, se puder!",
  ui_story_5009_50091301_52_dialog_content = "Ugh...",
  ui_story_5009_50091301_53_dialog_content = "Não podemos aguentar mais...",
  ui_story_5009_50091301_54_dialog_content = "Mirren! Sou a única representante de Lumópolis! Se deseja despejar sua ira sobre alguém, que seja em mim! Deixe-os em paz!",
  ui_story_5009_50091301_55_dialog_content = "Ah? Parece que disse algo interessante.",
  ui_story_5009_50091301_56_dialog_content = "O que foi isso agora? \"Deixe-os em paz?” Hahahaha! Não me faça rir!",
  ui_story_5009_50091301_57_dialog_content = "As vidas de seus camaradas são as únicas dignas de misericórdia? Onde estava essa mesma misericórdia quando minha família foi massacrada anos atrás?!",
  ui_story_5009_50091301_58_dialog_content = "Isso significa que as vidas dos familiares da Senhorita Paloma também não mereciam misericórdia. Certo?!",
  ui_story_5009_50091301_59_dialog_content = "Mirren Gautier... Sua família era inocente, mas você jamais será.",
  ui_story_5009_50091301_60_dialog_content = "Você escolheu se tornar um facínora, e fazendo isso condenou sua família inteira ao sofrimento e à morte.",
  ui_story_5009_50091301_61_dialog_content = "Suas palavras não valem nada.",
  ui_story_5009_50091301_62_dialog_content = "Bobagem... São as suas, não as minhas!",
  ui_story_5009_50091301_63_dialog_content = "Não passa de uma criatura egoísta… Isso acaba agora!",
  ui_story_5009_50091301_64_dialog_content = "Hahaha! Ignorando a razão novamente? Nossas famílias jamais teriam sido exiladas se não fosse por seu comportamento.",
  ui_story_5009_50091301_65_dialog_content = "Eu não tinha poder antes, e me atazanavam por causa disso.",
  ui_story_5009_50091301_66_dialog_content = "Mas assim que os adquiri, começaram a me temer, obedecer e... até me admirar...",
  ui_story_5009_50091301_67_dialog_content = "Infelizmente, minha família não entendeu e nem aceitou isso, então Lumópolis se encarregou deles.",
  ui_story_5009_50091301_68_dialog_content = "Quanto a mim, adoro ver seus rostos apavorados, hipócritas e indefesos diante do meu poder.",
  ui_story_5009_50091301_69_dialog_content = "Essa é a minha justiça.",
  ui_story_5009_50091301_70_dialog_content = "Mais um monólogo pomposo sobre poder... Cansei de ouvir essa bobagem.",
  ui_story_5009_50091301_71_dialog_content = "Você não tem direito de falar sobre justiça a partir do momento em que vendeu sua alma por poder.",
  ui_story_5009_50091301_72_dialog_content = "E não fale da sua família como se não passasse de uma mera ferramenta para você.",
  ui_story_5009_50091301_73_dialog_content = "Mirren... Você é sempre dramático ou esse é outro efeito da sua transformação?",
  ui_story_5009_50091301_74_dialog_content = "Rá!",
  ui_story_5009_50091301_78_dialog_content = "Hunf, minha paciência esgotou.",
  ui_story_5009_50091301_79_dialog_content = "Hora de mandar vocês para o inferno, junto com o resto dos Celestitas!",
  ui_story_5009_50091301_75_dialog_content = "PlayerName, saia da frente!",
  ui_story_5009_50091301_A3_dialog_content = "Só por cima do meu cadáver!",
  ui_story_5009_50091301_80_dialog_content = "Paloma… Você ainda pode lutar?",
  ui_story_5009_50091301_82_dialog_content = "O quê?!",
  ui_story_5009_50091301_A4_dialog_content = "Não pare aí desse jeito. Tente me acompanhar. Vamos atacar juntos… Não pare até acabar!",
  ui_story_5009_50091301_A5_dialog_content = "Então vocês sabem mesmo o que é trabalho em equipe! Soldados, sigam-me!",
  ui_story_5009_50091301_A6_dialog_content = "Não tenho outra escolha… Gelescer!",
  ui_story_5009_50091301_A7_dialog_content = "Aceite sua sentença!",
  ui_story_5009_50091301_A8_dialog_content = "Isso mesmo, pessoal… Não vamos tolerar isso!",
  ui_story_5009_50091301_76_dialog_content = "Hunf...",
  ui_story_5009_50091301_77_option_content = "Conexão mental!",
  ui_story_5009_50091301_A9_dialog_content = "Ai… minha cabeça...",
  ui_story_5009_50091301_A10_dialog_content = "Mas isso é de Eraveil… Não é…",
  ui_story_5009_50091301_A11_dialog_content = "É de verdade? Meu controle de Luminática parece que melhorou um pouco!",
  ui_story_5009_50091301_A12_dialog_content = "Digo o mesmo.",
  ui_story_5009_50091301_A13_dialog_content = "Os ataques de todos estão funcionando… Estamos nos libertando do controle desse lugar!",
  ui_story_5009_50091301_81_dialog_content = "Minhas habilidades psíquicas também voltaram parcialmente!",
  ui_story_5009_50091301_83_dialog_content = "Mirren Gautier... Não importa o que você fez ou o sofrimento que causou no passado...",
  ui_story_5009_50091301_84_dialog_content = "Você trouxe destruição para Eraveil em nome do Eclipse!",
  ui_story_5009_50091301_85_dialog_content = "Jamais te perdoarei por isso!",
  ui_story_5009_50091301_86_dialog_content = "Hahahaha! Palavras tão fortes para uma criatura tão frágil!",
  ui_story_5009_50091301_87_dialog_content = "Muito bem! Já que vai ser assim... Vou usar todo o meu poder pra te esmagar!",
  ui_story_5009_50091301_88_dialog_content = "Grrrrr!",
  ui_story_5009_50091301_89_dialog_content = "Todos preparados? É hora de acabar com isso!",
  ui_story_5009_50091301_90_dialog_content = "Seus poderes psíquicos... Já os recuperou?",
  ui_story_5009_50091301_91_dialog_content = "Hunf, sempre estive preparado. Vamos nessa!",
  ui_story_5009_50091301_92_option_content = "Ativar poderes!",
  ui_story_5009_50091302_1_dialog_content = "Essa luz é tão brilhante...",
  ui_story_5009_50091302_2_dialog_content = "Droga! O Eclipse está começando a desaparecer.",
  ui_story_5009_50091302_3_dialog_content = "De novo! Ele fugiu...",
  ui_story_5009_50091302_4_dialog_content = "Mirren Gautier... astuto, como sempre.",
  ui_story_5009_50091302_5_dialog_content = "Assim que o jogo começa a virar, ele usa toda a sua esperteza pra se safar.",
  ui_story_5009_50091302_6_dialog_content = "Realmente ferimos ele dessa vez. Temo que não teremos notícias por um bom tempo.",
  ui_story_5009_50091302_7_dialog_content = "Mirren Gautier... Ele veio para Eraveil dezessete anos atrás?",
  ui_story_5009_50091302_8_dialog_content = "Por que pergunta?",
  ui_story_5009_50091302_9_dialog_content = "Dezessete anos atrás, quando Eraveil e os Celestitas foram exterminados... ocorreu um Eclipse no céu. igual ao de hoje.",
  ui_story_5009_50091302_10_dialog_content = "Pensei que talvez tivesse...",
  ui_story_5009_50091302_11_dialog_content = "Desculpe, mas até onde eu sei...",
  ui_story_5009_50091302_12_dialog_content = "Antes de nossas famílias serem exiladas e enviadas para Baixa Lumópolis, eu não acho que Mirren já tivesse saído de Lumópolis.",
  ui_story_5009_50091302_13_dialog_content = "Quando suas famílias foram exiladas?",
  ui_story_5009_50091302_14_dialog_content = "Doze anos atrás.",
  ui_story_5009_50091302_15_dialog_content = "Então... Não foi ele?",
  ui_story_5009_50091302_16_dialog_content = "Pelo que juntamos, creio...",
  ui_story_5009_50091302_17_dialog_content = "É bem provável que o tal \"mestre\" de Mirren esteja envolvido.",
  ui_story_5009_50091302_18_dialog_content = "...!",
  ui_story_5009_50091302_19_dialog_content = "Paloma, quanto você realmente sabe sobre o Eclipse?",
  ui_story_5009_50091302_20_dialog_content = "Gostaria de saber o mesmo!",
  ui_story_5009_50091302_21_dialog_content = "A aparição do Eclipse... provavelmente é um poder da organização deles.",
  ui_story_5009_50091302_22_dialog_content = "Em áreas afetadas pelo Eclipse, a Luminática das pessoas é enfraquecida em vários níveis.",
  ui_story_5009_50091302_23_dialog_content = "As minhas habilidades psíquicas também foram afetadas desde o início...",
  ui_story_5009_50091302_24_dialog_content = "E o tal espaço estranho? O que era?",
  ui_story_5009_50091302_25_dialog_content = "Era algo tipo uma área de Eclipse selada e concentrada, onde seus efeitos de enfraquecimento são ainda mais intensos.",
  ui_story_5009_50091302_26_dialog_content = "É muito difícil romper esse espaço por dentro, mas é bem mais fácil destruí-lo por fora.",
  ui_story_5009_50091302_27_dialog_content = "Sobre o mestre...",
  ui_story_5009_50091302_28_dialog_content = "Meu povo... Os Celestitas foram destruídos pelo mesmo tipo de ataque?",
  ui_story_5009_50091302_29_dialog_content = "Como sabe tanto sobre Mirren Gautier, Paloma? Ou sobre como o Eclipse funciona?",
  ui_story_5009_50091302_30_dialog_content = "Ah? Está suspeitando de mim agora?",
  ui_story_5009_50091302_31_dialog_content = "D-Desculpe.",
  ui_story_5009_50091302_32_dialog_content = "Só tenho uma curiosidade. Por que seus poderes não foram afetados pelo Eclipse?",
  ui_story_5009_50091302_33_dialog_content = "Quando se deixa levar pela sede de vingança, não percebe mais nada.",
  ui_story_5009_50091302_34_dialog_content = "É apenas o preço que devo pagar. Receio que jamais entenda.",
  ui_story_5009_50091302_35_dialog_content = "Também quer se vingar de Lumópolis?",
  ui_story_5009_50091302_36_dialog_content = "Ahn? Parece estar mais ciente do que pensei, Princesa de Lumópolis...",
  ui_story_5009_50091302_37_dialog_content = "Acalme-se. Não chegou a hora de Lumópolis... ainda.",
  ui_story_5009_50091302_38_dialog_content = "Então é bom saber que não permitirei que nenhum mal aconteça a Lumópolis e seu povo.",
  ui_story_5009_50091302_39_dialog_content = "Hum... Teremos que esperar para ver, não é mesmo?",
  ui_story_5009_50091302_40_dialog_content = "Vingança...",
  ui_story_5009_50091302_41_dialog_content = "Eu não sei sobre os outros... Mas tenho certeza que você entende o sentimento muito bem, PlayerName.",
  ui_story_5009_50091302_42_dialog_content = "...Escolheria se tornar Eclipsita só por vingança?",
  ui_story_5009_50091302_43_dialog_content = "Sua piada é um pouco sem graça para o meu gosto, PlayerName.",
  ui_story_5009_50091302_44_dialog_content = "Então me diga, VOCÊ se tornaria Eclipsita só por uma questão de vingança?",
  ui_story_5009_50091302_45_dialog_content = "Claro que não!",
  ui_story_5009_50091302_46_dialog_content = "Então somos dois!",
  ui_story_5009_50091302_47_dialog_content = "Hahaha... Sinto que temos muito mais em comum, PlayerName. No entanto...",
  ui_story_5009_50091302_48_dialog_content = "Também acho que esse papo não leva a lugar nenhum. É melhor eu ir embora.",
  ui_story_5009_50091302_49_dialog_content = "Paloma.",
  ui_story_5009_50091302_50_dialog_content = "Você e Beryl...",
  ui_story_5009_50091302_51_dialog_content = "Ah... eu sei o que você está tentando perguntar, PlayerName.",
  ui_story_5009_50091302_52_dialog_content = "Minha vingança não tem nada a ver com Beryl.",
  ui_story_5009_50091302_53_dialog_content = "E então... ela está bem?",
  ui_story_5009_50091302_54_dialog_content = "Hunf, vocês não estão trabalhando juntos para reconstruir os Correios?",
  ui_story_5009_50091302_55_dialog_content = "Se quer mesmo saber, basta escrever uma carta e perguntar direto.",
  ui_story_5009_50091302_56_dialog_content = "Tô indo agora.",
  ui_story_5009_50091302_57_dialog_content = "Espere, Senhorita Paloma.",
  ui_story_5009_50091302_58_dialog_content = "O quê? Pensando em me prender antes que eu fuja?",
  ui_story_5009_50091302_59_dialog_content = "Desejo reabrir a investigação sobre as famílias Pyrrhus e Gautier para continuar pesquisando sobre essa questão.",
  ui_story_5009_50091302_60_dialog_content = "Obviamente, se voltasse comigo para a Corte de Justiça...",
  ui_story_5009_50091302_61_dialog_content = "E daí? Te dar a chance de cumprir seu dever me prendendo?",
  ui_story_5009_50091302_62_dialog_content = "Por favor, Paloma! Você sabe que não sou esse tipo de pessoa!",
  ui_story_5009_50091302_63_dialog_content = "Quero saber a verdade, assim podemos colocar os pingos nos is.",
  ui_story_5009_50091302_64_dialog_content = "É mesmo? Então me diga, sabe por que as elites de Lumópolis preferiram ocultar a verdade?",
  ui_story_5009_50091302_65_dialog_content = "Sabe quem está por trás de tudo isso?",
  ui_story_5009_50091302_66_dialog_content = "Claro que não sabe.",
  ui_story_5009_50091302_67_dialog_content = "Isso mesmo. Não sei e nem preciso.",
  ui_story_5009_50091302_68_dialog_content = "Só preciso saber que devo investigar a verdade.",
  ui_story_5009_50091302_69_dialog_content = "...Hã?",
  ui_story_5009_50091302_70_dialog_content = "Na ocasião, enviaram a mim e vários colegas até Umbraton para investigar o assunto, mas acabamos encontrando integrantes do Eclipse...",
  ui_story_5009_50091302_71_dialog_content = "*Tosse* Tem certeza...?",
  ui_story_5009_50091302_72_dialog_content = "Pittman... Minhas pernas já não aguentam...",
  ui_story_5009_50091302_73_dialog_content = "Mas você... e os outros...",
  ui_story_5009_50091302_74_dialog_content = "Se continuar perdendo tempo, todos seremos exterminados!",
  ui_story_5009_50091302_75_dialog_content = "Vá, agora!",
  ui_story_5009_50091302_76_dialog_content = "Pais e filhos, maridos e esposas...",
  ui_story_5009_50091302_77_dialog_content = "Já que só eu sobrevivi ao ataque, devo a todos uma explicação pelas mortes de seus entes queridos.",
  ui_story_5009_50091302_78_dialog_content = "Acho que agora entendo seus sentimentos um pouco melhor... Mas, Vossa Alteza, pare com esses pensamentos hipócritas!",
  ui_story_5009_50091302_79_dialog_content = "Na sua posição atual, nunca conseguirá encontrar a verdade.",
  ui_story_5009_50091302_80_dialog_content = "O Deus da Luz me confiou tal tarefa. Não posso e nem falharei com minhas obrigações.",
  ui_story_5009_50091302_81_dialog_content = "A justiça pode demorar bastante, mas algum dia será feita!",
  ui_story_5009_50091302_82_dialog_content = "......",
  ui_story_5009_50091302_83_dialog_content = "*Suspiro*",
  ui_story_5009_50091302_84_dialog_content = "Desejo-lhe sorte.",
  ui_story_5009_50091302_85_dialog_content = "Até nos encontrarmos novamente, PlayerName!",
  ui_story_5009_50091302_86_dialog_content = "Paloma! Espere!",
  ui_story_5009_50091302_87_dialog_content = "......",
  ui_story_5009_50091302_88_dialog_content = "Tudo bem... deixar uma fugitiva ir embora assim?",
  ui_story_5009_50091302_89_dialog_content = "Não vamos nos envolver.",
  ui_story_5009_50091302_90_dialog_content = "O que vai dizer aos seus superiores, Pittman?",
  ui_story_5009_50091302_91_dialog_content = "A verdade, Srta. Carleen. Informarei toda a verdade.",
  ui_story_5009_50091302_92_dialog_content = "Mas não teme que a Corte de Justiça responsabilize você pela fuga do fugitivo?",
  ui_story_5009_50091302_93_dialog_content = "Aparentemente um número de casos da última década era mais complexo que parecia e, por isso, precisam de mais investigação.",
  ui_story_5009_50091302_94_dialog_content = "Creio que a Corte de Justiça, assim como a Juíza chefe, não vão ignorar a necessidade de esclarecer esses casos, muito menos me punir sem motivo.",
  ui_story_5009_50091302_95_dialog_content = "Em nome do Deus da Luz, juro que desvendarei a verdade, custe o que custar.",
  ui_story_5009_50091302_96_dialog_content = "Lumópolis é abençoada por ter alguém com sua determinação. Acredito em sua casa",
  ui_story_5009_50091302_97_dialog_content = "Eu... também acredito em você, Pittman!",
  ui_story_5009_50091302_98_dialog_content = "*limpa a garganta* Ei, PlayerName!",
  ui_story_5009_50091302_99_dialog_content = "Ainda recorda o que viemos fazer?",
  ui_story_5009_50091302_100_option_content = "Lembro...",
  ui_story_5009_50091302_101_dialog_content = "Viemos ver Eraveil.",
  ui_story_5009_50091302_102_option_content = "Esqueci totalmente...",
  ui_story_5009_50091302_103_dialog_content = "*Suspira* Não viemos ajudar a reconstruir o Posto?",
  ui_story_5009_50091302_104_dialog_content = "Será que o Eclipse afetou Naroxel e os demais?",
  ui_story_5009_50091302_105_dialog_content = "Não esquentaria a cachola com isso.",
  ui_story_5009_50091302_106_dialog_content = "Recuperamos as comunicações, e a julgar pela mensagem grave que ela enviou...",
  ui_story_5009_50091302_107_dialog_content = "Parece que estão atarefados.",
  ui_story_5009_50091302_108_dialog_content = "Então, ainda não podemos nos dar ao luxo de descansar.",
  ui_story_5009_50091302_109_dialog_content = "Há algum Eclipsite remanescente escondido em Eraveil, PlayerName?",
  ui_story_5009_50091302_110_dialog_content = "Sim... posso sentir que ainda restam alguns Eclipsitas inferiores à espreita nas proximidades.",
  ui_story_5009_50091302_111_dialog_content = "Então, vamos despachar todos e acabar logo com isso.",
  ui_story_5009_50091302_112_dialog_content = "Vamos eliminar todos antes do anoitecer, pessoal!",
  ui_story_5009_50091302_113_dialog_content = "Vamos!",
  ui_story_5009_50091302_114_dialog_content = "Ai...",
  ui_story_5009_50091302_115_dialog_content = "Estão indo para o lado errado... Os Eclipsitas estão ali!",
  ui_story_5009_50091401_1_dialog_content = "Parece que vai escurecer logo.",
  ui_story_5009_50091401_2_dialog_content = "relatório de estado, PlayerName?",
  ui_story_5009_50091401_3_dialog_content = "Eraveil está...",
  ui_story_5009_50091401_4_dialog_content = "Ainda sobraram alguns, é? Sério... não tem como se livrar deles!",
  ui_story_5009_50091401_5_dialog_content = "Cadê o resto? Não podem se esconder de mim!",
  ui_story_5009_50091401_6_dialog_content = "Não vejo nenhum Eclipsita em Eraveil!",
  ui_story_5009_50091401_7_dialog_content = "Eu falei! Sabia que podíamos acabar com todos antes do anoitecer!",
  ui_story_5009_50091401_8_dialog_content = "Parabéns, pessoal. Tudo é possível, desde que a gente nunca desista.",
  ui_story_5009_50091401_9_dialog_content = "Os Eclipsitas já eram?",
  ui_story_5009_50091401_10_dialog_content = "Espera aí... vencemos?",
  ui_story_5009_50091401_11_dialog_content = "Sim, conseguimos... Graças à colaboração de todos.",
  ui_story_5009_50091401_12_dialog_content = "Isso aí! Ganhamos!",
  ui_story_5009_50091401_13_dialog_content = "<color=#e8d9bb>Buzz, buzz... Buzz...</color>",
  ui_story_5009_50091401_14_dialog_content = "Hum? Espere... Que som é esse?",
  ui_story_5009_50091401_15_dialog_content = "Ah, é só uma notificação do meu terminal.",
  ui_story_5009_50091401_16_dialog_content = "D-Desculpe, só vou dar uma conferida rapidinho...",
  ui_story_5009_50091401_17_dialog_content = "Saudações, Vice.",
  ui_story_5009_50091401_18_dialog_content = "É Naroxel!",
  ui_story_5009_50091401_19_dialog_content = "Olá, Naroxel! Tudo bem?",
  ui_story_5009_50091401_20_dialog_content = "Oh? parece PlayerName está com você também.",
  ui_story_5009_50091401_21_dialog_content = "Qual é a situação em Eraveil? A área ainda está cheia de Eclipsitas?",
  ui_story_5009_50091401_22_dialog_content = "Ah, não esquenta! Graças à ajuda de todos, acabamos com os Eclipsitas de Eraveil!",
  ui_story_5009_50091401_23_dialog_content = "Graças às bençãos da natureza! No início, estava me preocupando muito com o seu bem-estar.",
  ui_story_5009_50091401_24_dialog_content = "Mas, te ver com tanta energia me acalmou.",
  ui_story_5009_50091401_25_dialog_content = "Na verdade, foi um... dia longo. Como estão as coisas do seu lado? Algum problema grave?",
  ui_story_5009_50091401_26_dialog_content = "Tudo tranquilo... Mas a doença de Dove ainda é preocupante.",
  ui_story_5009_50091401_27_dialog_content = "Espere... Dove apareceu?",
  ui_story_5009_50091401_28_dialog_content = "Sim, mas estava muito doente e todos perceberam que ela precisava descansar. Providenciei um veículo para levá-la de volta o mais rápido possível.",
  ui_story_5009_50091401_29_dialog_content = "*Suspiro* Me pergunto se aquela pombinha está fingindo de novo só pra se livrar do trampo...",
  ui_story_5009_50091401_30_dialog_content = "Duvido, já que a doença dela é resultado do grande esforço dedicado a este trabalho.",
  ui_story_5009_50091401_31_dialog_content = "Não sabia que Dove era capaz de se esforçar tanto...",
  ui_story_5009_50091401_32_dialog_content = "Ela realmente ajudou muito hoje. Venha ver por si só, você vai perceber do que estou falando.",
  ui_story_5009_50091401_33_dialog_content = "Ahn? T-Tá bom, então.",
  ui_story_5009_50091401_34_dialog_content = "Ah, e Tweety pediu pra te dizer que tem uma grande surpresa para vocês no Posto.",
  ui_story_5009_50091401_35_dialog_content = "Porém... Saber disso não estraga a surpresa?",
  ui_story_5009_50091401_36_dialog_content = "De qualquer maneira, devem estar exaustos após um dia tão longo.",
  ui_story_5009_50091401_37_dialog_content = "Preparamos chá quente e lanches para vocês nos Correios, como forma de boas-vindas.",
  ui_story_5009_50091401_38_dialog_content = "Entendido! Logo estaremos aí. Até mais!",
  ui_story_5009_50091401_39_dialog_content = "O que será que ela quis dizer com \"grande surpresa\"?",
  ui_story_5009_50091401_40_dialog_content = "Não tenho certeza, mas ela sempre levou jeito para fazer o inesperado. Mal vejo a hora de descobrir o que é.",
  ui_story_5009_50091401_41_dialog_content = "Só espero que a surpresa seja boa e não uma decepção.",
  ui_story_5009_50091401_42_dialog_content = "Agora que Eraveil está livre de qualquer ameaça Eclipsita...",
  ui_story_5009_50091401_43_dialog_content = "Sua Alteza, PlayerName, Vice... Acho que está na hora de eu voltar a Lumopolis para fazer meu relatório.",
  ui_story_5009_50091401_44_dialog_content = "Como é? Já tá indo embora?",
  ui_story_5009_50091401_45_dialog_content = "Qual é, Pittman. Sei que a Corte de Justiça não se importará se decidir ficar mais um pouco.",
  ui_story_5009_50091401_46_dialog_content = "Não precisa ter pressa.",
  ui_story_5009_50091401_47_dialog_content = "Isso aí! Sem dizer que hoje você ainda não tratou dos seus ferimentos...",
  ui_story_5009_50091401_48_dialog_content = "Que tal ficar com a gente e descansar um pouco? Será uma honra se aceitar ser nosso convidado!",
  ui_story_5009_50091401_49_dialog_content = "Agradeço pela hospitalidade, mas receio que devo recusar.",
  ui_story_5009_50091401_50_dialog_content = "Passar por tudo isso com vocês me fez repensar várias coisas... Além de fortalecer minha determinação.",
  ui_story_5009_50091401_51_dialog_content = "Graças a vocês, absorvi bastante conhecimento e obtive várias pistas da investigação aqui em Eraveil.",
  ui_story_5009_50091401_52_dialog_content = "Desejo fazer o meu relato o mais rápido possível e prosseguir com a minha investigação.",
  ui_story_5009_50091401_53_dialog_content = "Se é mesmo o que quer fazer, nós entendemos…",
  ui_story_5009_50091401_54_dialog_content = "Mas sempre que tiver um tempo livre, não se esqueça de vir nos ver de novo, tá?",
  ui_story_5009_50091401_55_dialog_content = "É claro, PlayerName. Eu tenho uma sensação...",
  ui_story_5009_50091401_56_dialog_content = "Que vamos nos ver de novo em breve.",
  ui_story_5009_50091401_57_dialog_content = "Como esses caras entram e saem como querem?",
  ui_story_5009_50091401_58_dialog_content = "Acho que não devíamos estar aqui, mas assistir ao drama se desenrolar é interessante, né?",
  ui_story_5009_50091401_59_dialog_content = "Cof! Tem algo que vocês queiram compartilhar com a gente, soldados?",
  ui_story_5009_50091401_60_dialog_content = "N-Não, senhora!",
  ui_story_5009_50091401_61_dialog_content = "N-Nós só estávamos conversando sobre a melhor forma de voltar!",
  ui_story_5009_50091401_62_dialog_content = "Se ninguém se importar, eu posso levar todos de volta na Colossus.",
  ui_story_5009_50091401_63_dialog_content = "Só tenho uma condição.",
  ui_story_5009_50091401_64_dialog_content = "Uma condição? Estavam aqui para ajudar! Não acha que é demais exigir uma condição?",
  ui_story_5009_50091401_65_dialog_content = "Escute o que tenho a dizer primeiro, Vice!",
  ui_story_5009_50091401_66_dialog_content = "Qual a sua condição? Estamos ouvindo.",
  ui_story_5009_50091401_67_dialog_content = "Vocês são os primeiros convidados que trago de volta para Eraveil, minha terra natal…",
  ui_story_5009_50091401_68_dialog_content = "Mas depois de tudo que passamos hoje, e toda a ajuda que vocês nos deram, eu sinto que sou um péssimo anfitrião…",
  ui_story_5009_50091401_69_dialog_content = "Então eu gostaria de pedir a todos… Vocês poderiam me dar outra chance de tratá-los como meus convidados e ser um bom anfitrião?",
  ui_story_5009_50091401_70_dialog_content = "É só isso? Hahaha! Para mim, não tem problema! O que vocês acham?",
  ui_story_5009_50091401_71_dialog_content = "Parece bom para mim! Finalmente, um descanso! Tudo bem!",
  ui_story_5009_50091401_72_dialog_content = "Eu sinto Muito, PlayerName... Acho que cheguei à conclusão errada.",
  ui_story_5009_50091401_73_dialog_content = "Mas como exatamente você pretende nos agradar?",
  ui_story_5009_50091401_74_dialog_content = "Bem, na verdade… Alguns dias atrás, eu decidi me preparar para o Dia Terravento…",
  ui_story_5009_50091401_75_dialog_content = "Pedi um monte de lanches e bebidas à União Mensageira. Eles devem chegar amanhã em alguma hora.",
  ui_story_5009_50091401_76_dialog_content = "PlayerName... Ocorreu a você olhar a planilha de despesas do Colosso antes de fazer qualquer pedido?!",
  ui_story_5009_50091401_77_dialog_content = "E-Enfim… Nós devíamos voltar para o Correio primeiro, não acham? Naroxel ainda está esperando por nós!",
  ui_story_5009_50091401_78_dialog_content = "Eles até prepararam chá e lanches para a gente!",
  ui_story_5009_50091401_79_dialog_content = "Sim! Vamos lá!",
  ui_story_5009_50091401_80_dialog_content = "<color=#e8d9bb>Growl...</color>",
  ui_story_5009_50091401_81_dialog_content = "Espere! Acho que ouvi o som de um Eclipsita agorinha!",
  ui_story_5009_50091401_82_dialog_content = "Sente alguma coisa, PlayerName?",
  ui_story_5009_50091401_83_dialog_content = "Ah… Desculpe, acho que foi meu estômago roncando…",
  ui_story_5009_50091401_84_dialog_content = "Alarme falso…",
  ui_story_5009_50091401_85_dialog_content = "Já que não tem nada para se preocupar, vamos um pouco mais rápido.",
  ui_story_5009_50091401_86_dialog_content = "Estamos quase no Correio, não vamos deixá-los esperando!",
  ui_story_5009_50091401_87_dialog_content = "Ok… Embora eu não possa dizer que meu estômago vazio não é “nada para se preocupar”…",
  ui_story_5009_50091401_88_dialog_content = "Você pode continuar andando, PlayerName? Ou devo pedir a Bessie que te carregue de volta?",
  ui_story_5009_50091401_89_dialog_content = "N-Naroxel?! Você estava aqui esse tempo todo?",
  ui_story_5009_50091401_90_dialog_content = "Sinto muito, te assustei?",
  ui_story_5009_50091401_91_dialog_content = "Tweety estava ficando preocupada porque vocês estavam demorando, então ela pediu para eu encontrá-los.",
  ui_story_5009_50091401_92_dialog_content = "Eu por acaso ouvi seu comentário assim que encontrei vocês…",
  ui_story_5009_50091401_93_dialog_content = "N-não é nada demais. Sério…",
  ui_story_5009_50091401_94_dialog_content = "Isso é muito gentil da parte de vocês, Naroxel, Tweety!",
  ui_story_5009_50091401_95_dialog_content = "Só que… Não vejo a Tweety em nenhum lugar.",
  ui_story_5009_50091401_96_dialog_content = "Talvez ela esteja com medo do escuro.",
  ui_story_5009_50091401_97_dialog_content = "Não, é só que… Alguém tem que ficar e vigiar o Correio, só isso.",
  ui_story_5009_50091401_98_dialog_content = "Parece que ela está ocupada preparando a sua “grande surpresa” lendária.",
  ui_story_5009_50091401_99_dialog_content = "De qualquer forma... Por aqui, pessoal!",
  ui_story_5009_50091401_100_dialog_content = "<color=#e8d9bb>Creeak...</color>",
  ui_story_5009_50091401_101_dialog_content = "Uau...!",
  ui_story_5009_50091401_102_dialog_content = "Essas prateleiras e aquele balcão… Todos parecem tão familiares.",
  ui_story_5009_50091401_103_dialog_content = "Se for o que estou pensando, o Correio em Lumópolis é projetado de forma parecida.",
  ui_story_5009_50091401_104_dialog_content = "Mas mesmo assim, essa caixa de correio é completamente diferente. De alguma forma, me lembra o Soroz…",
  ui_story_5009_50091401_105_dialog_content = "É isso mesmo. Essa é a caixa de correio de autoatendimento de Eraveil, projetada pelos próprios Celestitas.",
  ui_story_5009_50091401_106_dialog_content = "Felizmente, ainda funciona mesmo depois de tanto tempo.",
  ui_story_5009_50091401_107_dialog_content = "Ei, olha o que achei nessa prateleira aqui!",
  ui_story_5009_50091401_108_dialog_content = "Cartões pessoais… de dez anos atrás! Eu só vi algo assim no museu!",
  ui_story_5009_50091401_109_dialog_content = "Tem até um aquário aqui!",
  ui_story_5009_50091401_110_dialog_content = "Deixe Naroxel trazer o espírito da natureza para um lugar assim!",
  ui_story_5009_50091401_111_dialog_content = "Com relação a isso, Dove gastou muito tempo e energia para pegar o peixe que você vê dentro do aquário.",
  ui_story_5009_50091401_112_dialog_content = "Dove? Eu jamais adivinharia…",
  ui_story_5009_50091401_113_dialog_content = "Estou com tanto ciúme de você, PlayerName! Nenhum dos Postos da Federação Illumina é tão aconchegante quanto este!",
  ui_story_5009_50091401_114_dialog_content = "Hum? Por que você não está dizendo nada, PlayerName?",
  ui_story_5009_50091401_115_dialog_content = "Eu… Eu só estou muito animado. Tão animado… que não sei como expressar meus sentimentos neste momento.",
  ui_story_5009_50091401_116_dialog_content = "Esse é… o primeiro quarto em Eraveil a ter iluminação.",
  ui_story_5009_50091401_117_dialog_content = "E a decoração ficou tão bonita… Isso é mesmo só um Correio?",
  ui_story_5009_50091401_118_dialog_content = "Eu adoraria morar aqui, se possível…",
  ui_story_5009_50091401_119_dialog_content = "Miauu!",
  ui_story_5009_50091401_120_dialog_content = "Haha! Desculpa, parece que não será o primeiro residente daqui!",
  ui_story_5009_50091401_121_dialog_content = "Você sabe, PlayerName, se você realmente quisesse morar aqui... Você seria bem-vindo, como funcionário do Sindicato dos Correios!",
  ui_story_5009_50091401_122_dialog_content = "Mas antes disso… Você ainda se lembra dessa carta de admissão?",
  ui_story_5009_50091401_123_dialog_content = "Lembro, é que...",
  ui_story_5009_50091401_124_dialog_content = "Eu acho que não consigo entender porque agora estou muito cansado.",
  ui_story_5009_50091401_125_dialog_content = "Talvez você pudesse dar PlayerName os pontos principais da carta, Naroxel? Tudo bem?",
  ui_story_5009_50091401_126_dialog_content = "Sem problemas. Se a reconstrução desse Correio pela União Mensageira tiver atendido às suas expectativas…",
  ui_story_5009_50091401_127_dialog_content = "Na verdade, excedeu minhas expectativas… Tipo umas cem vezes mais!",
  ui_story_5009_50091401_128_dialog_content = "Agradeço pela sua contribuição. Então, se possível, assine, por favor, seu nome aqui embaixo, e lembre-se…",
  ui_story_5009_50091401_129_dialog_content = "Quando sua assinatura estiver completa, seu contrato com nossos Correios estará oficialmente em vigor.",
  ui_story_5009_50091401_130_dialog_content = "O que exatamente você quer dizer com “oficialmente em vigor”?",
  ui_story_5009_50091401_131_dialog_content = "Dentro da rede de transportes da União Mensageira, o ponto de referência para o Correio de Eraveil será aceso mais uma vez.",
  ui_story_5009_50091401_132_dialog_content = "Em outras palavras, Eraveil conseguirá receber correspondência do mundo todo.",
  ui_story_5009_50091401_133_dialog_content = "(Antes do desastre… as pessoas de Eraveil vinham aqui para receber cartas de Illumina e Lumópolis…)",
  ui_story_5009_50091401_134_dialog_content = "(E até de Northland?)",
  ui_story_5009_50091401_135_dialog_content = "(Isso quer dizer… que os Celestita também usaram esse lugar…)",
  ui_story_5009_50091401_136_dialog_content = "(Também para enviar mensagens ao mundo? Cartas com suas alegrias e tristezas?)",
  ui_story_5009_50091401_137_dialog_content = "(Se eu assinar meu nome, o Correio voltará a ser como antes… há dezessete anos.)",
  ui_story_5009_50091401_138_dialog_content = "(Se eu assinar meu nome, Eraveil vai surgir mais uma vez em todos os mapas do mundo…)",
  ui_story_5009_50091401_139_dialog_content = "Você ainda tem alguma dúvida ou preocupação, PlayerName?",
  ui_story_5009_50091401_140_dialog_content = "Não, eu só preciso saber onde assinar meu nome. Eu vou…",
  ui_story_5009_50091401_141_dialog_content = "Restabelecer Eraveil!",
  ui_story_5009_50091401_142_dialog_content = "Bem aqui, se possível. Eu acho que nunca vi alguém tão animado para assinar um contrato antes!",
  ui_story_5009_50091401_143_dialog_content = "Assinatura:",
  ui_story_5009_50091401_A1_dialog_content = "...",
  ui_story_5009_50091401_144_option_content = "PlayerName",
  ui_story_5009_50091401_145_dialog_content = "<color=#e8d9bb>Gongo... Gongo... Gongo...</color>",
  ui_story_5009_50091401_146_dialog_content = "Já é meia-noite?",
  ui_story_5009_50091401_147_dialog_content = "Eu nem percebi que já estava tão tarde.",
  ui_story_5009_50091401_148_dialog_content = "Já é o dia seguinte… Isso significa que é hora…",
  ui_story_5009_50091401_149_dialog_content = "Ugh...",
  ui_story_5009_50091401_150_dialog_content = "Hã? Carleen, cuidado!",
  ui_story_5009_50091401_151_dialog_content = "Dispersem, pétalas de gelo!",
  ui_story_5009_50091401_152_dialog_content = "Esse é… Soroz?",
  ui_story_5009_50091401_153_dialog_content = "Mas o material... É uma boneca de Soroz!",
  ui_story_5009_50091401_154_dialog_content = "É… tão… bonitinho! De onde veio isso?",
  ui_story_5009_50091401_155_dialog_content = "Essa deve ser a surpresa que Tweety estava falando. Foi uma surpresa chocante, afinal…",
  ui_story_5009_50091401_156_dialog_content = "Finalmente vocês me notalam!",
  ui_story_5009_50091401_157_dialog_content = "Hã? Aquela era a Tweety? Eu ouvi a voz dela, mas eu não a vejo em lugar algum…",
  ui_story_5009_50091401_158_dialog_content = "Tô aqui... O gelo de Caleen me pegou!",
  ui_story_5009_50091401_159_dialog_content = "Não tive escolha. Estava com medo que Tweety fosse cair também… Deixe-me desfazer o congelamento.",
  ui_story_5009_50091401_160_dialog_content = "Obrigada, Caleen! Mas... esqueceu que eu tenho asas?",
  ui_story_5009_50091401_161_dialog_content = "Mas ser congelada assim... foi legal!",
  ui_story_5009_50091401_162_dialog_content = "Então você quer que eu te congele de novo?",
  ui_story_5009_50091401_163_dialog_content = "N-Não, valeu! Uma vez é o bastante…",
  ui_story_5009_50091401_164_dialog_content = "Você ficou esperando nas vigas esse tempo todo, Tweety?",
  ui_story_5009_50091401_165_dialog_content = "Isso! Espelei todos desde o início!",
  ui_story_5009_50091401_166_dialog_content = "É que desse jeito eu podia descer lápido com minha glande sulplesa!",
  ui_story_5009_50091401_167_dialog_content = "Mas… Eu dolmi sem queler… E o sino me acoldou agolinha…",
  ui_story_5009_50091401_168_dialog_content = "Sowwy, PlayerName... Minha grande surpresa foi uma grande decepção ...",
  ui_story_5009_50091401_169_dialog_content = "Não tem motivos para se desculpar, Tweety! Você deixou esse lugar incrível... Nem tive tempo de te agradecer direito.",
  ui_story_5009_50091401_170_dialog_content = "Além disso, o sino da meia-noite acabou de tocar, o que significa que hoje é oficialmente o Festival Terravento.",
  ui_story_5009_50091401_171_dialog_content = "No livro diz que neste feriado os Celestitas também penduravam bonecas assim.",
  ui_story_5009_50091401_172_dialog_content = "Essa sua surpresa é absolutamente perfeita para a ocasião!",
  ui_story_5009_50091401_173_dialog_content = "S-Sélio? Estou tão feliz em ouvir isso!",
  ui_story_5009_50091401_174_dialog_content = "Então você realmente gostou da minha surpresa, PlayerName?",
  ui_story_5009_50091401_175_dialog_content = "Claro que sim! Mas onde você achou algo assim?",
  ui_story_5009_50091401_176_dialog_content = "Essa foi... a nossa melhor tentativa de recriar uma pequena versão de Soroz.",
  ui_story_5009_50091401_177_dialog_content = "Não está perfeito, de forma alguma… Mas nós ENCHEMOS ele com lanches reais!",
  ui_story_5009_50091401_178_dialog_content = "É também a nossa forma de lhe dar os nossos melhores votos, PlayerName!",
  ui_story_5009_50091401_179_dialog_content = "Parece mesmo com Soroz! Além disso, é bem melhor do que qualquer coisa que fiz…",
  ui_story_5009_50091401_180_dialog_content = "Oh? Isso quer dizer que o boneco aranha na Colossus, aquele com olhos de sapo e asas de morcego…",
  ui_story_5009_50091401_181_dialog_content = "Esse foi o seu trabalho, PlayerName?",
  ui_story_5009_50091401_182_dialog_content = "P-Para, Vice! Os outros não podem saber disso…",
  ui_story_5009_50091401_183_dialog_content = "Então PlayerName? Quer abrir e dobrar os lanches dentro?",
  ui_story_5009_50091401_184_dialog_content = "Eu escolhi todos especialmente pala você!",
  ui_story_5009_50091401_185_dialog_content = "Mas você e a Naroxel trabalharam tanto, Tweety. Sem falar que ele parece com Soroz…",
  ui_story_5009_50091401_186_dialog_content = "Acho que não consigo quebrar.",
  ui_story_5009_50091401_187_dialog_content = "B-Mas se você não o enfraquecer, não será uma verdadeira celebridade, PlayerName...",
  ui_story_5009_50091401_188_dialog_content = "Você já esqueceu, Tweety?",
  ui_story_5009_50091401_189_dialog_content = "Ah! Veldade! Dove fez aquelas luzes voadolas chiques também!",
  ui_story_5009_50091401_190_dialog_content = "Luzes… voadoras?",
  ui_story_5009_50091401_191_dialog_content = "Ela está falando das Lanternas de Dente-de-leão que os Celestitas acendiam durante os feriados?",
  ui_story_5009_50091401_192_dialog_content = "Espera... Dove consegue fazer Lanternas de Dente-de-leão?!",
  ui_story_5009_50091401_193_dialog_content = "Eu já perguntei, mas ainda estamos falando da mesma Dove?!",
  ui_story_5009_50091401_194_dialog_content = "Dove disse que ela aprendeu muito em Illumina…",
  ui_story_5009_50091401_195_dialog_content = "Ela acabou encontrando um guia de como criar Lanternas de Dente-de-Leão e o pegou sem pensar duas vezes.",
  ui_story_5009_50091401_196_dialog_content = "Mal posso espela pala blincá com as luzes bontinhas!",
  ui_story_5009_50091401_197_dialog_content = "Vamos pala a platafolma!",
  ui_story_5009_50091401_198_dialog_content = "C-cuidado onde pisa, Tweety! Não corra tão rápido!",
  ui_story_5009_50091401_199_dialog_content = "Está tudo celto! Eu tenho asas, lembla?",
  ui_story_5009_50091401_200_dialog_content = "<color=#e8d9bb>Batida...!</color>",
  ui_story_5009_50091401_201_dialog_content = "Ai…",
  ui_story_5009_50091401_202_dialog_content = "Você tá bem, Tweety? Você teve uma queda feia! Tá doendo?",
  ui_story_5009_50091401_203_dialog_content = "Obligada, Vice... Não está mais doendo.",
  ui_story_5009_50091401_204_dialog_content = "Eu só esbalei em uma lantelna, só isso... me queimei um pouco, mas já estou bem!",
  ui_story_5009_50091401_205_dialog_content = "Eles realmente parecem dentes-de-leão quando você os acende…",
  ui_story_5009_50091401_206_dialog_content = "PlayerName, conte até três, e vamos soltar nossas Lanternas Dente-de-leão ao mesmo tempo, ok?",
  ui_story_5009_50091401_207_dialog_content = "Beleza! Um… Dois… Três! Subam!",
  ui_story_5009_50091401_208_dialog_content = "Vai, vai, vai!",
  ui_story_5009_50091401_209_dialog_content = "Lanternas brilhando em contraste com inúmeras estrelas e uma aurora brilhante… Uma visão rara que enche os olhos e o coração de admiração.",
  ui_story_5009_50091401_210_dialog_content = "Já faz um tempo desde que eu ouvi você dizer algo tão poético, Carleen!",
  ui_story_5009_50091401_211_dialog_content = "Um feriado lindo como esse não estaria completo sem um poema ou dois.",
  ui_story_5009_50091401_212_dialog_content = "Vice, você devia ter tido mais aulas de literatura durante seus estudos em Lumópolis.",
  ui_story_5009_50091401_213_dialog_content = "Se for o caso, uma competição de poesia talvez seja propícia.",
  ui_story_5009_50091401_214_dialog_content = "Eu nunca entendi literatura ou poesia, mas agora…",
  ui_story_5009_50091401_215_dialog_content = "Por um momento, eu senti como se as pessoas que já partiram há tempos estivessem ao meu lado.",
  ui_story_5009_50091401_216_dialog_content = "E então, elas riam conforme se viravam, levando meus pensamentos e desejos com elas…",
  ui_story_5009_50091401_217_dialog_content = "Acho que nós todos deveríamos fazer um desejo!",
  ui_story_5009_50091401_218_dialog_content = "Mas não me lembro do Windland Festival ter esse tipo de tradição? O que você acha, PlayerName?",
  ui_story_5009_50091401_219_dialog_content = "Olhem ali, pessoal! Meus olhos estão me enganando ou tem algo voando na nossa direção?",
  ui_story_5009_50091401_220_dialog_content = "Como imaginei, parece que o Correio vai ficar cheio no seu primeiro dia de funcionamento.",
  ui_story_5009_50091401_221_dialog_content = "Então aquelas coisas no céu…",
  ui_story_5009_50091401_222_dialog_content = "Acredito que sejam mensageiros carregando cartas de todo o mundo, PlayerName.",
  ui_story_5009_50091401_223_dialog_content = "Nunca percebi que a União Mensageira trabalhava tão depressa…",
  ui_story_5009_50091401_224_dialog_content = "PlayerName acabou de assinar o nome dele há poucos minutos, e já estão aparecendo!",
  ui_story_5009_50091401_225_dialog_content = "Então as cartas que eles estão carregando…",
  ui_story_5009_50091401_226_dialog_content = "Exatamente. São as cartas que seriam entregues ao povo de Eraveil nos últimos dezessete anos.",
  ui_story_5009_50091401_227_dialog_content = "E hoje, no dia do Festival Terravento…",
  ui_story_5009_50091401_228_dialog_content = "Suas esperanças, suas preocupações, suas vozes… Elas finalmente chegarão ao seu destino.",
  ui_story_5009_50091401_229_dialog_content = "Ainda assim, eu nunca pensei…",
  ui_story_5009_50091401_230_dialog_content = "Que tantos mensageiros estariam disponíveis para entregar cartas equivalentes a dezessete anos de uma vez. É realmente uma vista e tanto para contemplar.",
  ui_story_5009_50091401_231_dialog_content = "Você vai estar ocupada nos próximos dias, Tweety.",
  ui_story_5009_50091401_232_dialog_content = "Uhum! Pla mim está bem, gosto do meu tlabalho!",
  ui_story_5009_50091401_233_dialog_content = "Se pelo menos a Tweety pudesse trabalhar em Illumina…",
  ui_story_5009_50091401_234_dialog_content = "Isso selia ótimo! Assim, eu podelia vê Dove todos os dias!",
  ui_story_5009_50091401_235_dialog_content = "Mas eu não sei se algum dia conseguilia deixá o ninho dos meus amigos de Nolthland pala tlás...",
  ui_story_5009_50091401_236_dialog_content = "Acabei de vê uma velha amiga! Ela está vindo pala entlegá as caltas!",
  ui_story_5009_50091401_237_dialog_content = "Não tão rápido, Tweety!",
  ui_story_5009_50091401_238_dialog_content = "<color=#e8d9bb>Batida...!</color>",
  ui_story_5009_50091401_239_dialog_content = "Ain... O que está no meu rosto? Isso coça...",
  ui_story_5009_50091401_240_dialog_content = "Você bateu em uma das Lanternas de Dente-de-leão, Tweety… Sua cara está cheia de felpo branco!",
  ui_story_5009_50091401_241_dialog_content = "Hahaha! Que fofinha! Acho que combina com ela!",
  ui_story_5009_50091401_242_dialog_content = "He...",
  ui_story_5009_50091401_243_dialog_content = "Nossa, eu consegui! Finalmente fiz a Caleen dá um solliso! Hahaha!",
  ui_story_5009_50091401_244_dialog_content = "Hahahahaha!",
  ui_story_5009_50091401_245_dialog_content = "E então, foi assim que eu passei meu primeiro Festival Terravento.",
  ui_story_5009_50091401_246_dialog_content = "Antes do festival…",
  ui_story_5009_50091401_247_dialog_content = "Havia dor…",
  ui_story_5009_50091401_248_dialog_content = "Havia raiva…",
  ui_story_5009_50091401_249_dialog_content = "Havia mudança…",
  ui_story_5009_50091401_250_dialog_content = "E houve despedidas…",
  ui_story_5009_50091401_251_dialog_content = "Acontece que existem muitas pessoas assim como eu no mundo.",
  ui_story_5009_50091401_252_dialog_content = "Mas por causa das escolhas que fizemos, seguimos por caminhos diferentes na vida.",
  ui_story_5009_50091401_253_dialog_content = "No momento em que nossos destinos divergem, tudo que podemos fazer é dar adeus um para o outro…",
  ui_story_5009_50091401_254_dialog_content = "Mas acho que, desde que façamos nossas escolhas com a consciência limpa, talvez possamos ser amigos algum dia.",
  ui_story_5009_50091401_255_dialog_content = "E que algum dia, aqueles traidores egoístas e maldosos vão ter o que merecem também.",
  ui_story_5009_50091401_256_dialog_content = "Depois de tudo que eu passei, não consigo deixar de agradecer pelos amigos que fiz ao longo do caminho.",
  ui_story_5009_50091401_257_dialog_content = "Principalmente… em um feriado como esse.",
  ui_story_5009_50091401_258_dialog_content = "Eu via os feriados como dias comuns. Eu não entendia o objetivo de celebrar nada.",
  ui_story_5009_50091401_259_dialog_content = "Mas agora, eu finalmente entendo.",
  ui_story_5009_50091401_260_dialog_content = "Em um dia especial, ser capaz de relembrar com seus amigos e compartilhar suas esperanças para o futuro…",
  ui_story_5009_50091401_261_dialog_content = "É uma coisa muito acolhedora e auspiciosa de viver.",
  ui_story_5009_50091401_262_dialog_content = "Nesses últimos dias, o Correio recebeu muitas cartas de todo lugar, a qualquer hora do dia.",
  ui_story_5009_50091401_263_dialog_content = "Embora a maioria delas não fossem para mim…",
  ui_story_5009_50091401_264_dialog_content = "Mas Naroxel diz que, como último Celestita, eu posso agir como último destinatário deles e abri-las, se eu quiser.",
  ui_story_5009_50091401_265_dialog_content = "“Atender aos desejos de todos é um conceito bem romântico”.",
  ui_story_5009_50091401_266_dialog_content = "Meu povo querido que já partiu gostaria que eu continuasse a carregar seus pensamentos e sentimentos?",
  ui_story_5009_50091401_267_dialog_content = "Todos dizem que eles obviamente iriam querer…",
  ui_story_5009_50091401_268_dialog_content = "Mas antes de qualquer coisa, eu decidi… que eu tenho que enviar minha primeira carta de Eraveil.",
  ui_story_5009_50091401_269_dialog_content = "Escrevo em meu diário todos os dias, mas escrever uma carta é diferente.",
  ui_story_5009_50091401_270_dialog_content = "Continuo preocupado que minhas palavras não combinem com a ocasião. Continuo reescrevendo e apagando meus pensamentos…",
  ui_story_5009_50091401_271_dialog_content = "Afinal, estou representando todos os Celestitas ao agradecer a todos por tudo que eles têm feito por nós.",
  ui_story_5009_50091401_272_dialog_content = "Hum… Me pergunto se eles receberam minha carta…",
  ui_story_5009_50091401_273_dialog_content = "A família Lin em Umbraton…"
}
return config
